window.KB_QUESTIONS = [{"id":"cng_j001_q1","tid":"cng_j001","ty":"choice","df":"basic","p":"地球在太阳系中属于哪一类天体？","ch":[{"key":"A","text":"恒星"},{"key":"B","text":"卫星"},{"key":"C","text":"行星"},{"key":"D","text":"彗星"}],"a":"C","ex":"地球围绕太阳公转，是太阳系中的一颗行星。"},{"id":"cng_j001_q2","tid":"cng_j001","ty":"choice","df":"basic","p":"月球属于哪一类天体？","ch":[{"key":"A","text":"恒星"},{"key":"B","text":"行星"},{"key":"C","text":"星云"},{"key":"D","text":"卫星"}],"a":"D","ex":"月球围绕地球运转，是地球的天然卫星。"},{"id":"cng_j001_q3","tid":"cng_j001","ty":"choice","df":"standard","p":"太阳系八大行星按距太阳由近及远，地球排在第几位？","ch":[{"key":"A","text":"第三位"},{"key":"B","text":"第一位"},{"key":"C","text":"第五位"},{"key":"D","text":"第八位"}],"a":"A","ex":"顺序是水星、金星、地球、火星、木星、土星、天王星、海王星。"},{"id":"cng_j001_q4","tid":"cng_j001","ty":"choice","df":"challenge","p":"可观测宇宙中，地球所在的天体系统由小到大依次是？","ch":[{"key":"A","text":"太阳系、地月系、银河系、可观测宇宙"},{"key":"B","text":"地月系、太阳系、银河系、可观测宇宙"},{"key":"C","text":"银河系、太阳系、地月系、可观测宇宙"},{"key":"D","text":"地月系、银河系、太阳系、可观测宇宙"}],"a":"B","ex":"地球和月球组成地月系，地月系属于太阳系，太阳系属于银河系。"},{"id":"cng_j002_q1","tid":"cng_j002","ty":"choice","df":"basic","p":"地球的平均半径大约是？","ch":[{"key":"A","text":"40000千米"},{"key":"B","text":"5.1亿千米"},{"key":"C","text":"384000千米"},{"key":"D","text":"6371千米"}],"a":"D","ex":"教材给出地球平均半径约6371千米。"},{"id":"cng_j002_q2","tid":"cng_j002","ty":"choice","df":"basic","p":"0°经线又称为？","ch":[{"key":"A","text":"本初子午线"},{"key":"B","text":"赤道"},{"key":"C","text":"国际日期变更线"},{"key":"D","text":"北回归线"}],"a":"A","ex":"0°经线穿过英国格林尼治，称为本初子午线。"},{"id":"cng_j002_q3","tid":"cng_j002","ty":"choice","df":"standard","p":"纬线指示的方向是？","ch":[{"key":"A","text":"南北方向"},{"key":"B","text":"东西方向"},{"key":"C","text":"上下方向"},{"key":"D","text":"西北—东南方向"}],"a":"B","ex":"纬线与经线垂直，指示东西方向；经线指示南北方向。"},{"id":"cng_j002_q4","tid":"cng_j002","ty":"choice","df":"challenge","p":"北纬40°、东经116°大致对应的城市是？","ch":[{"key":"A","text":"新加坡"},{"key":"B","text":"开普敦"},{"key":"C","text":"北京"},{"key":"D","text":"纽约"}],"a":"C","ex":"北京大约位于40°N、116°E附近。"},{"id":"cng_j003_q1","tid":"cng_j003","ty":"choice","df":"basic","p":"地球自转的方向是？","ch":[{"key":"A","text":"自西向东"},{"key":"B","text":"自东向西"},{"key":"C","text":"自北向南"},{"key":"D","text":"自南向北"}],"a":"A","ex":"从北极上空看，地球自转呈逆时针，即自西向东。"},{"id":"cng_j003_q2","tid":"cng_j003","ty":"choice","df":"basic","p":"昼夜交替主要是由哪一种运动引起的？","ch":[{"key":"A","text":"地球公转"},{"key":"B","text":"地球自转"},{"key":"C","text":"月球绕地球运动"},{"key":"D","text":"太阳黑子活动"}],"a":"B","ex":"地球不停自转，朝向太阳的一面是白天，背向太阳的一面是黑夜。"},{"id":"cng_j003_q3","tid":"cng_j003","ty":"choice","df":"standard","p":"北半球夏至日，太阳直射的纬线是？","ch":[{"key":"A","text":"赤道"},{"key":"B","text":"南回归线"},{"key":"C","text":"北回归线"},{"key":"D","text":"北极圈"}],"a":"C","ex":"夏至日太阳直射北回归线（约23.5°N），北半球昼最长。"},{"id":"cng_j003_q4","tid":"cng_j003","ty":"choice","df":"challenge","p":"地球公转产生的地理现象是？","ch":[{"key":"A","text":"昼夜更替"},{"key":"B","text":"地方时差异"},{"key":"C","text":"物体水平运动方向偏转"},{"key":"D","text":"四季更替和五带划分"}],"a":"D","ex":"公转使太阳直射点在南北回归线之间移动，从而形成四季和五带。"},{"id":"cng_j004_q1","tid":"cng_j004","ty":"choice","df":"basic","p":"地图的三要素是？","ch":[{"key":"A","text":"经线、纬线、赤道"},{"key":"B","text":"比例尺、方向、图例"},{"key":"C","text":"海拔、相对高度、等高线"},{"key":"D","text":"图名、页码、附录"}],"a":"B","ex":"比例尺、方向和图例是阅读地图必须掌握的三项基本要素。"},{"id":"cng_j004_q2","tid":"cng_j004","ty":"choice","df":"basic","p":"在没有指向标的一般地图上，默认方向是？","ch":[{"key":"A","text":"上南下北，左东右西"},{"key":"B","text":"上东下西，左北右南"},{"key":"C","text":"上北下南，左西右东"},{"key":"D","text":"上西下东，左南右北"}],"a":"C","ex":"普通地图通常按上北下南、左西右东定向。"},{"id":"cng_j004_q3","tid":"cng_j004","ty":"choice","df":"standard","p":"相同图幅下，比例尺越大，表示的实地范围？","ch":[{"key":"A","text":"越大，内容越简略"},{"key":"B","text":"不变，内容一样详细"},{"key":"C","text":"越大，内容越详细"},{"key":"D","text":"越小，内容越详细"}],"a":"D","ex":"比例尺大则同一图幅覆盖的实地范围小，地理事物可以画得更详细。"},{"id":"cng_j004_q4","tid":"cng_j004","ty":"choice","df":"challenge","p":"数字式比例尺 1:100000 表示图上 1 厘米代表实地？","ch":[{"key":"A","text":"1千米"},{"key":"B","text":"100千米"},{"key":"C","text":"10米"},{"key":"D","text":"1米"}],"a":"A","ex":"1:100000 即图上 1 厘米代表实地 100000 厘米，也就是 1 千米。"},{"id":"cng_j005_q1","tid":"cng_j005","ty":"choice","df":"basic","p":"等高线地形图上，等高线越密集，表示？","ch":[{"key":"A","text":"坡度越缓"},{"key":"B","text":"海拔越低"},{"key":"C","text":"坡度越陡"},{"key":"D","text":"一定是山谷"}],"a":"C","ex":"相邻等高线水平距离越小，坡度越陡。"},{"id":"cng_j005_q2","tid":"cng_j005","ty":"choice","df":"basic","p":"海拔一般在 200 米以下、地面平坦广阔的地形是？","ch":[{"key":"A","text":"高原"},{"key":"B","text":"山地"},{"key":"C","text":"丘陵"},{"key":"D","text":"平原"}],"a":"D","ex":"平原海拔较低，地势平坦。"},{"id":"cng_j005_q3","tid":"cng_j005","ty":"choice","df":"standard","p":"等高线向海拔高处凸出的部位通常是？","ch":[{"key":"A","text":"山谷"},{"key":"B","text":"山脊"},{"key":"C","text":"鞍部"},{"key":"D","text":"陡崖"}],"a":"A","ex":"“凸高为谷，凸低为脊”，等高线向高处凸是山谷。"},{"id":"cng_j005_q4","tid":"cng_j005","ty":"choice","df":"challenge","p":"分层设色地形图上，绿色通常表示？","ch":[{"key":"A","text":"高山冰雪"},{"key":"B","text":"平原或低地"},{"key":"C","text":"海洋最深处"},{"key":"D","text":"沙漠"}],"a":"B","ex":"陆地上绿色多表示海拔较低的平原，黄色、褐色表示更高的高原山地。"},{"id":"cng_j006_q1","tid":"cng_j006","ty":"choice","df":"basic","p":"查找北京到上海的铁路路线，最合适的是？","ch":[{"key":"A","text":"世界气候图"},{"key":"B","text":"北京市区旅游图"},{"key":"C","text":"等高线地形图"},{"key":"D","text":"中国交通图"}],"a":"D","ex":"交通图专门表示铁路、公路等线路。"},{"id":"cng_j006_q2","tid":"cng_j006","ty":"choice","df":"basic","p":"去公园徒步，要判断哪条路更陡，应优先看？","ch":[{"key":"A","text":"等高线地形图"},{"key":"B","text":"世界政区图"},{"key":"C","text":"人口分布图"},{"key":"D","text":"语言分布图"}],"a":"A","ex":"等高线可以反映坡度陡缓，适合选择登山或徒步路线。"},{"id":"cng_j006_q3","tid":"cng_j006","ty":"choice","df":"standard","p":"比例尺很小的世界地图，适合用来？","ch":[{"key":"A","text":"查找某条胡同的门牌"},{"key":"B","text":"了解大洲大洋的相对位置"},{"key":"C","text":"量算校园操场长度"},{"key":"D","text":"辨别小区内部道路"}],"a":"B","ex":"小比例尺地图表示范围大、内容简略，适合看大区域位置。"},{"id":"cng_j006_q4","tid":"cng_j006","ty":"choice","df":"challenge","p":"既要看清某省各市位置，又要大致了解地形起伏，较合适的组合是？","ch":[{"key":"A","text":"只有世界气候类型图"},{"key":"B","text":"只有太阳系示意图"},{"key":"C","text":"省级政区图和地形图"},{"key":"D","text":"只有城市公交线路图"}],"a":"C","ex":"政区图给出行政区位置，地形图给出地势起伏，二者配合使用。"},{"id":"cng_j007_q1","tid":"cng_j007","ty":"choice","df":"basic","p":"地球表面海洋与陆地面积大约是？","ch":[{"key":"A","text":"海洋约 71%，陆地约 29%"},{"key":"B","text":"各占一半"},{"key":"C","text":"陆地约 71%，海洋约 29%"},{"key":"D","text":"海洋约 90%，陆地约 10%"}],"a":"A","ex":"全球约十分之七是海洋，十分之三是陆地。"},{"id":"cng_j007_q2","tid":"cng_j007","ty":"choice","df":"basic","p":"面积最大的大洲是？","ch":[{"key":"A","text":"非洲"},{"key":"B","text":"亚洲"},{"key":"C","text":"南极洲"},{"key":"D","text":"欧洲"}],"a":"B","ex":"亚洲是世界第一大洲，面积约 4400 万平方千米。"},{"id":"cng_j007_q3","tid":"cng_j007","ty":"choice","df":"standard","p":"亚洲与非洲的分界线是？","ch":[{"key":"A","text":"巴拿马运河"},{"key":"B","text":"白令海峡"},{"key":"C","text":"苏伊士运河"},{"key":"D","text":"乌拉尔山脉"}],"a":"C","ex":"苏伊士运河沟通地中海和红海，是亚非分界。"},{"id":"cng_j007_q4","tid":"cng_j007","ty":"choice","df":"challenge","p":"七大洲按面积从大到小，正确的一组口诀是？","ch":[{"key":"A","text":"亚欧非北美，南美南极大洋"},{"key":"B","text":"非亚北美欧，南美南极大洋"},{"key":"C","text":"亚非欧北美，南美南极大洋"},{"key":"D","text":"亚非北南美，南极欧大洋"}],"a":"D","ex":"口诀“亚非北南美，南极欧大洋”对应亚洲、非洲、北美洲、南美洲、南极洲、欧洲、大洋洲。"},{"id":"cng_j008_q1","tid":"cng_j008","ty":"choice","df":"basic","p":"陆地五种基本地形是？","ch":[{"key":"A","text":"平原、沙漠、绿洲、峡谷、岛屿"},{"key":"B","text":"平原、高原、山地、丘陵、盆地"},{"key":"C","text":"海洋、湖泊、河流、冰川、沼泽"},{"key":"D","text":"半岛、群岛、海峡、海湾、海岸"}],"a":"B","ex":"教材把陆地地形分为平原、高原、山地、丘陵和盆地。"},{"id":"cng_j008_q2","tid":"cng_j008","ty":"choice","df":"basic","p":"世界最高大的山脉是？","ch":[{"key":"A","text":"安第斯山脉"},{"key":"B","text":"阿尔卑斯山脉"},{"key":"C","text":"喜马拉雅山脉"},{"key":"D","text":"落基山脉"}],"a":"C","ex":"喜马拉雅山脉位于亚洲中部，主峰珠穆朗玛峰是世界最高峰。"},{"id":"cng_j008_q3","tid":"cng_j008","ty":"choice","df":"standard","p":"安第斯山脉主要位于哪个大洲？","ch":[{"key":"A","text":"非洲"},{"key":"B","text":"欧洲"},{"key":"C","text":"大洋洲"},{"key":"D","text":"南美洲"}],"a":"D","ex":"安第斯山脉纵贯南美洲西部，是世界上最长的山脉。"},{"id":"cng_j008_q4","tid":"cng_j008","ty":"choice","df":"challenge","p":"亚马孙平原成为世界最大平原，主要因为它位于？","ch":[{"key":"A","text":"南美洲赤道附近的亚马孙河流域"},{"key":"B","text":"非洲北部的撒哈拉沙漠"},{"key":"C","text":"亚洲中部的青藏高原"},{"key":"D","text":"北美洲中部的落基山麓"}],"a":"A","ex":"亚马孙河流域地势低平，形成广阔的冲积平原。"},{"id":"cng_j009_q1","tid":"cng_j009","ty":"choice","df":"basic","p":"海陆变迁的重要证据之一是？","ch":[{"key":"A","text":"四季更替"},{"key":"B","text":"昼夜长短变化"},{"key":"C","text":"有的高山上发现海洋生物化石"},{"key":"D","text":"地图上的比例尺大小"}],"a":"C","ex":"高山上的海相化石说明那里曾经是海洋。"},{"id":"cng_j009_q2","tid":"cng_j009","ty":"choice","df":"basic","p":"魏格纳提出的学说是？","ch":[{"key":"A","text":"日心说"},{"key":"B","text":"地心说"},{"key":"C","text":"宇宙大爆炸说"},{"key":"D","text":"大陆漂移说"}],"a":"D","ex":"魏格纳根据南美洲和非洲轮廓吻合等现象提出大陆漂移说。"},{"id":"cng_j009_q3","tid":"cng_j009","ty":"choice","df":"standard","p":"世界火山、地震主要集中在？","ch":[{"key":"A","text":"板块交界地带"},{"key":"B","text":"大陆内部的平原中心"},{"key":"C","text":"大洋中部远离海沟处"},{"key":"D","text":"所有赤道地区"}],"a":"A","ex":"板块交界地壳活跃，多火山地震。"},{"id":"cng_j009_q4","tid":"cng_j009","ty":"choice","df":"challenge","p":"红海面积在不断扩大，主要是因为两侧板块在？","ch":[{"key":"A","text":"碰撞挤压"},{"key":"B","text":"张裂拉伸"},{"key":"C","text":"水平错动但完全静止"},{"key":"D","text":"整体向地心沉降"}],"a":"B","ex":"红海位于非洲板块与印度洋板块张裂地带，海域逐渐扩大。"},{"id":"cng_j010_q1","tid":"cng_j010","ty":"choice","df":"basic","p":"“今天多云，明天有中雨”描述的是？","ch":[{"key":"A","text":"气候"},{"key":"B","text":"地形"},{"key":"C","text":"洋流"},{"key":"D","text":"天气"}],"a":"D","ex":"天气是短时间的大气状况，气候是长时间的平均状况。"},{"id":"cng_j010_q2","tid":"cng_j010","ty":"choice","df":"basic","p":"天气预报里，带雨点的云朵符号通常表示？","ch":[{"key":"A","text":"降雨"},{"key":"B","text":"沙尘暴"},{"key":"C","text":"大雾"},{"key":"D","text":"霜冻"}],"a":"A","ex":"云加雨点是降雨天气符号。"},{"id":"cng_j010_q3","tid":"cng_j010","ty":"choice","df":"standard","p":"空气质量指数（AQI）数值越大，通常表示？","ch":[{"key":"A","text":"气温越高"},{"key":"B","text":"空气污染越重"},{"key":"C","text":"风力越大"},{"key":"D","text":"空气越清洁"}],"a":"B","ex":"AQI 用来表示空气质量，数值越大污染越重。"},{"id":"cng_j010_q4","tid":"cng_j010","ty":"choice","df":"challenge","p":"下列叙述属于气候的是？","ch":[{"key":"A","text":"今晚有雷阵雨"},{"key":"B","text":"明天最低气温 8℃"},{"key":"C","text":"昆明四季如春"},{"key":"D","text":"刚才刮起了大风"}],"a":"C","ex":"“四季如春”是长期大气状况，属于气候；其余都是短时天气。"},{"id":"cng_j011_q1","tid":"cng_j011","ty":"choice","df":"basic","p":"一天中，陆地最高气温通常出现在？","ch":[{"key":"A","text":"午后 2 时左右"},{"key":"B","text":"正午 12 时整"},{"key":"C","text":"日出前后"},{"key":"D","text":"午夜 0 时"}],"a":"A","ex":"地面热量积累到午后达到最高，陆地最高气温多在 14 时左右。"},{"id":"cng_j011_q2","tid":"cng_j011","ty":"choice","df":"basic","p":"世界气温分布的基本规律是？","ch":[{"key":"A","text":"由高纬向低纬递减"},{"key":"B","text":"由低纬向高纬递减"},{"key":"C","text":"只随经度变化"},{"key":"D","text":"全球各地完全相同"}],"a":"B","ex":"太阳辐射由赤道向两极递减，气温大致由低纬向高纬降低。"},{"id":"cng_j011_q3","tid":"cng_j011","ty":"choice","df":"standard","p":"同纬度地区，海拔每升高 1000 米，气温大约？","ch":[{"key":"A","text":"上升 6℃"},{"key":"B","text":"下降 1℃"},{"key":"C","text":"下降 6℃"},{"key":"D","text":"不变"}],"a":"C","ex":"对流层气温随海拔升高而降低，大约每千米下降 6℃。"},{"id":"cng_j011_q4","tid":"cng_j011","ty":"choice","df":"challenge","p":"等温线在北半球陆地 1 月向南凸出，主要说明？","ch":[{"key":"A","text":"同纬度陆地比海洋更热"},{"key":"B","text":"海拔越高气温越高"},{"key":"C","text":"该地一定位于南半球"},{"key":"D","text":"同纬度陆地比海洋更冷"}],"a":"D","ex":"1 月是北半球冬季，陆地降温快，同纬度陆地气温低于海洋，等温线向低纬（南）凸出。"},{"id":"cng_j012_q1","tid":"cng_j012","ty":"choice","df":"basic","p":"赤道附近地区年降水量通常？","ch":[{"key":"A","text":"非常稀少"},{"key":"B","text":"很丰富"},{"key":"C","text":"全年为零"},{"key":"D","text":"只在冬季较多"}],"a":"B","ex":"赤道地区空气对流旺盛，多对流雨，是世界多雨带。"},{"id":"cng_j012_q2","tid":"cng_j012","ty":"choice","df":"basic","p":"副热带地区的大陆西岸和内陆，降水往往？","ch":[{"key":"A","text":"非常丰富"},{"key":"B","text":"全年阴雨"},{"key":"C","text":"较少"},{"key":"D","text":"只在夜间下雨"}],"a":"C","ex":"副热带高气压控制下气流下沉，加上大陆内部水汽少，降水稀少。"},{"id":"cng_j012_q3","tid":"cng_j012","ty":"choice","df":"standard","p":"温带海洋性气候的降水特点是？","ch":[{"key":"A","text":"夏季暴雨、冬季滴雨没有"},{"key":"B","text":"全年干旱"},{"key":"C","text":"只有春季下雨"},{"key":"D","text":"全年湿润，各月比较均匀"}],"a":"D","ex":"西风常年影响，降水季节分配较均匀。"},{"id":"cng_j012_q4","tid":"cng_j012","ty":"choice","df":"challenge","p":"迎风坡降水往往多于背风坡，主要是因为？","ch":[{"key":"A","text":"湿润气流被迫抬升冷却致雨"},{"key":"B","text":"背风坡一定没有河流"},{"key":"C","text":"迎风坡海拔一定更低"},{"key":"D","text":"地球自转在迎风坡停止"}],"a":"A","ex":"地形雨：湿润气流沿山坡上升冷却凝结，背风坡气流下沉增温，降水减少。"},{"id":"cng_j013_q1","tid":"cng_j013","ty":"choice","df":"basic","p":"热带雨林气候主要分布在？","ch":[{"key":"A","text":"南北极圈以内"},{"key":"B","text":"青藏高原"},{"key":"C","text":"赤道附近"},{"key":"D","text":"回归线穿过的大陆西岸"}],"a":"C","ex":"赤道附近终年高温多雨，形成热带雨林气候。"},{"id":"cng_j013_q2","tid":"cng_j013","ty":"choice","df":"basic","p":"地中海气候的特征是？","ch":[{"key":"A","text":"全年高温多雨"},{"key":"B","text":"冬季严寒漫长"},{"key":"C","text":"全年寒冷干燥"},{"key":"D","text":"夏季炎热干燥，冬季温和多雨"}],"a":"D","ex":"地中海气候受副高和西风交替控制，雨热不同期。"},{"id":"cng_j013_q3","tid":"cng_j013","ty":"choice","df":"standard","p":"亚洲东部季风气候显著，其降水主要集中在？","ch":[{"key":"A","text":"夏季"},{"key":"B","text":"冬季"},{"key":"C","text":"春秋两季平均且极少"},{"key":"D","text":"全年各月都几乎无雨"}],"a":"A","ex":"夏季风从海洋带来大量水汽，雨热同期。"},{"id":"cng_j013_q4","tid":"cng_j013","ty":"choice","df":"challenge","p":"温带海洋性气候主要分布在？","ch":[{"key":"A","text":"赤道两侧"},{"key":"B","text":"南北纬 40°–60°的大陆西岸"},{"key":"C","text":"中亚内陆"},{"key":"D","text":"南极大陆内部"}],"a":"B","ex":"这里常年受西风和暖流影响，冬暖夏凉、降水均匀。"},{"id":"cng_j014_q1","tid":"cng_j014","ty":"choice","df":"basic","p":"目前世界人口最多的大洲是？","ch":[{"key":"A","text":"欧洲"},{"key":"B","text":"大洋洲"},{"key":"C","text":"南极洲"},{"key":"D","text":"亚洲"}],"a":"D","ex":"亚洲人口占世界一半以上。"},{"id":"cng_j014_q2","tid":"cng_j014","ty":"choice","df":"basic","p":"世界人口分布稠密区多位于？","ch":[{"key":"A","text":"中低纬度的近海平原"},{"key":"B","text":"高山高原内部"},{"key":"C","text":"热带沙漠腹地"},{"key":"D","text":"南极大陆"}],"a":"A","ex":"自然条件较好、开发较早的沿海平原人口密集。"},{"id":"cng_j014_q3","tid":"cng_j014","ty":"choice","df":"standard","p":"黄色人种主要分布在？","ch":[{"key":"A","text":"欧洲西部"},{"key":"B","text":"亚洲东部和东南部"},{"key":"C","text":"非洲中部"},{"key":"D","text":"澳大利亚中部沙漠"}],"a":"B","ex":"东亚、东南亚以黄色人种为主。"},{"id":"cng_j014_q4","tid":"cng_j014","ty":"choice","df":"challenge","p":"人口自然增长率最高的大洲通常是？","ch":[{"key":"A","text":"欧洲"},{"key":"B","text":"北美洲"},{"key":"C","text":"非洲"},{"key":"D","text":"大洋洲"}],"a":"C","ex":"非洲许多国家出生率高，人口增长快。"},{"id":"cng_j015_q1","tid":"cng_j015","ty":"choice","df":"basic","p":"聚落通常分为？","ch":[{"key":"A","text":"乡村和城镇"},{"key":"B","text":"只有首都和港口"},{"key":"C","text":"只有工厂和农田"},{"key":"D","text":"只有高原和盆地"}],"a":"A","ex":"人类集中居住的地方称为聚落，主要分为乡村和城镇。"},{"id":"cng_j015_q2","tid":"cng_j015","ty":"choice","df":"basic","p":"乡村聚落的居民一般主要从事？","ch":[{"key":"A","text":"国际贸易结算"},{"key":"B","text":"农业生产"},{"key":"C","text":"航天发射"},{"key":"D","text":"深海钻探"}],"a":"B","ex":"乡村以农业活动为主，城镇以非农业活动为主。"},{"id":"cng_j015_q3","tid":"cng_j015","ty":"choice","df":"standard","p":"沿河或沿交通线呈条带状分布的聚落，形态上属于？","ch":[{"key":"A","text":"团块状聚落"},{"key":"B","text":"完全没有形态"},{"key":"C","text":"带状聚落"},{"key":"D","text":"只出现在沙漠腹地"}],"a":"C","ex":"受河流、山谷或交通线限制，聚落常沿线延伸。"},{"id":"cng_j015_q4","tid":"cng_j015","ty":"choice","df":"challenge","p":"早期城市多出现在河流中下游平原，主要是因为？","ch":[{"key":"A","text":"完全没有水患风险"},{"key":"B","text":"这里一定没有农业"},{"key":"C","text":"海拔越高越适合建城"},{"key":"D","text":"水源充足、交通便利、农业基础好"}],"a":"D","ex":"平原土壤肥沃、用水方便、便于运输，有利于城市形成。"},{"id":"cng_j016_q1","tid":"cng_j016","ty":"choice","df":"basic","p":"使用人数最多的语言是？","ch":[{"key":"A","text":"英语"},{"key":"B","text":"汉语"},{"key":"C","text":"阿拉伯语"},{"key":"D","text":"西班牙语"}],"a":"B","ex":"汉语是世界上使用人数最多的语言；英语是使用最广泛的语言之一。"},{"id":"cng_j016_q2","tid":"cng_j016","ty":"choice","df":"basic","p":"基督教、伊斯兰教、佛教通常并称为？","ch":[{"key":"A","text":"亚洲仅有的方言"},{"key":"B","text":"四大洋的别称"},{"key":"C","text":"世界三大宗教"},{"key":"D","text":"七大洲的别称"}],"a":"C","ex":"这三大宗教信徒多、分布广，是世界主要宗教。"},{"id":"cng_j016_q3","tid":"cng_j016","ty":"choice","df":"standard","p":"佛教发源于？","ch":[{"key":"A","text":"古代希腊"},{"key":"B","text":"古代埃及"},{"key":"C","text":"古代罗马"},{"key":"D","text":"古代印度"}],"a":"D","ex":"佛教起源于南亚的古代印度，后传到东亚、东南亚等地。"},{"id":"cng_j016_q4","tid":"cng_j016","ty":"choice","df":"challenge","p":"语言和宗教的分布差异，说明世界文化具有？","ch":[{"key":"A","text":"多样性"},{"key":"B","text":"完全同一性"},{"key":"C","text":"只存在于城市"},{"key":"D","text":"与地理位置无关"}],"a":"A","ex":"不同地区的语言、宗教、建筑和习俗不同，体现文化多样性。"},{"id":"cng_j017_q1","tid":"cng_j017","ty":"choice","df":"basic","p":"目前世界上大多数国家属于？","ch":[{"key":"A","text":"发达国家"},{"key":"B","text":"没有常住人口的国家"},{"key":"C","text":"发展中国家"},{"key":"D","text":"极地科学考察站"}],"a":"C","ex":"发达国家数量较少，发展中国家占大多数。"},{"id":"cng_j017_q2","tid":"cng_j017","ty":"choice","df":"basic","p":"发达国家主要分布在？","ch":[{"key":"A","text":"非洲中部和西亚沙漠"},{"key":"B","text":"南极大陆内部"},{"key":"C","text":"全部位于赤道"},{"key":"D","text":"欧洲西部、北美洲、大洋洲等地"}],"a":"D","ex":"欧洲西部、美国、加拿大、澳大利亚、日本等属于发达国家。"},{"id":"cng_j017_q3","tid":"cng_j017","ty":"choice","df":"standard","p":"南南合作指的是？","ch":[{"key":"A","text":"发展中国家之间的合作"},{"key":"B","text":"发达国家与南极之间的合作"},{"key":"C","text":"只发生在南半球的贸易"},{"key":"D","text":"南北半球必须中断往来"}],"a":"A","ex":"发展中国家多在南半球及北半球南部，它们之间的合作称南南合作。"},{"id":"cng_j017_q4","tid":"cng_j017","ty":"choice","df":"challenge","p":"国际合作日益重要，主要是因为？","ch":[{"key":"A","text":"每个国家都可以完全自给自足"},{"key":"B","text":"各国在资源、资金、技术上相互依存"},{"key":"C","text":"交通和通信已经停止发展"},{"key":"D","text":"只有发达国家需要进口"}],"a":"B","ex":"经济全球化使国家之间在贸易、资源和环境问题上需要合作。"},{"id":"cng_j018_q1","tid":"cng_j018","ty":"choice","df":"basic","p":"亚洲大部分位于哪个半球？","ch":[{"key":"A","text":"南半球和西半球"},{"key":"B","text":"只在西半球"},{"key":"C","text":"只在南半球"},{"key":"D","text":"北半球和东半球"}],"a":"D","ex":"亚洲主体在赤道以北、20°W 以东，主要位于北半球、东半球。"},{"id":"cng_j018_q2","tid":"cng_j018","ty":"choice","df":"basic","p":"亚洲的地势特征是？","ch":[{"key":"A","text":"中部高，四周低"},{"key":"B","text":"东高西低"},{"key":"C","text":"北高南低且全是平原"},{"key":"D","text":"四周高，中部低"}],"a":"A","ex":"青藏高原和帕米尔高原雄踞中部，四周分布着较低的平原和丘陵。"},{"id":"cng_j018_q3","tid":"cng_j018","ty":"choice","df":"standard","p":"亚洲大河多呈放射状流向周边海洋，主要原因是？","ch":[{"key":"A","text":"全部发源于沿海平原"},{"key":"B","text":"地势中部高、四周低"},{"key":"C","text":"没有高原山地"},{"key":"D","text":"地球自转在亚洲停止"}],"a":"B","ex":"河流由高处流向低处，中部高四周低使大河向四周分流。"},{"id":"cng_j018_q4","tid":"cng_j018","ty":"choice","df":"challenge","p":"亚洲分布最广的气候类型是？","ch":[{"key":"A","text":"热带雨林气候"},{"key":"B","text":"温带海洋性气候"},{"key":"C","text":"温带大陆性气候"},{"key":"D","text":"极地气候"}],"a":"C","ex":"亚洲内陆面积广大，温带大陆性气候分布最广；东部季风气候也十分显著。"},{"id":"cng_j019_q1","tid":"cng_j019","ty":"choice","df":"basic","p":"亚洲是世界上人口最多的大洲，人口主要集中在？","ch":[{"key":"A","text":"东亚、东南亚和南亚"},{"key":"B","text":"北亚和中亚内陆"},{"key":"C","text":"西亚沙漠腹地"},{"key":"D","text":"青藏高原内部"}],"a":"A","ex":"东亚、东南亚、南亚自然条件较好，是人口稠密区。"},{"id":"cng_j019_q2","tid":"cng_j019","ty":"choice","df":"basic","p":"亚洲国家中，日本、韩国等属于？","ch":[{"key":"A","text":"全部是最不发达国家"},{"key":"B","text":"发达国家或经济发展水平较高的国家"},{"key":"C","text":"没有工业的国家"},{"key":"D","text":"只有畜牧业的国家"}],"a":"B","ex":"东亚一些国家工业化程度高，日本是发达国家。"},{"id":"cng_j019_q3","tid":"cng_j019","ty":"choice","df":"standard","p":"亚洲文化具有明显的？","ch":[{"key":"A","text":"完全单一性"},{"key":"B","text":"只存在一种语言"},{"key":"C","text":"多样性和东西差异"},{"key":"D","text":"与自然环境无关"}],"a":"C","ex":"亚洲地域辽阔，语言、宗教、建筑和习俗差异很大。"},{"id":"cng_j019_q4","tid":"cng_j019","ty":"choice","df":"challenge","p":"西亚部分国家因大量出口石油而较富裕，说明？","ch":[{"key":"A","text":"所有亚洲国家都同样富裕"},{"key":"B","text":"没有石油就无法发展任何产业"},{"key":"C","text":"人口越少经济一定越落后"},{"key":"D","text":"自然资源会影响区域经济发展水平"}],"a":"D","ex":"石油资源给西亚产油国带来较高收入，但发展仍受多种因素影响。"},{"id":"cng_j020_q1","tid":"cng_j020","ty":"choice","df":"basic","p":"日本是位于亚洲东部的？","ch":[{"key":"A","text":"内陆国"},{"key":"B","text":"岛国"},{"key":"C","text":"半岛国家"},{"key":"D","text":"大陆国家"}],"a":"B","ex":"日本由北海道、本州、四国、九州等岛屿组成。"},{"id":"cng_j020_q2","tid":"cng_j020","ty":"choice","df":"basic","p":"日本多火山地震，主要因为位于？","ch":[{"key":"A","text":"非洲板块内部"},{"key":"B","text":"南极板块中心"},{"key":"C","text":"板块交界地带"},{"key":"D","text":"太平洋正中央且远离海沟"}],"a":"C","ex":"日本处在太平洋板块与亚欧板块交界处，地壳活跃。"},{"id":"cng_j020_q3","tid":"cng_j020","ty":"choice","df":"standard","p":"日本工业集中分布在？","ch":[{"key":"A","text":"北海道内陆山地"},{"key":"B","text":"琉球群岛的最高峰上"},{"key":"C","text":"日本海沿岸的所有高山顶部"},{"key":"D","text":"太平洋沿岸和濑户内海沿岸"}],"a":"D","ex":"沿海多优良港湾，便于进口原料、出口产品。"},{"id":"cng_j020_q4","tid":"cng_j020","ty":"choice","df":"challenge","p":"日本气候的海洋性特征比较明显，表现为？","ch":[{"key":"A","text":"冬季较温和、降水较多"},{"key":"B","text":"全年炎热干燥"},{"key":"C","text":"没有四季变化"},{"key":"D","text":"与大陆内部完全相同"}],"a":"A","ex":"四周临海，受海洋调节，气温年较差较小，降水较丰富。"},{"id":"cng_j021_q1","tid":"cng_j021","ty":"choice","df":"basic","p":"东南亚处在亚洲与大洋洲、印度洋与太平洋之间的？","ch":[{"key":"A","text":"大陆内部"},{"key":"B","text":"极地地区"},{"key":"C","text":"“十字路口”"},{"key":"D","text":"世界屋脊"}],"a":"C","ex":"中南半岛和马来群岛扼守两洲两洋的交通要道。"},{"id":"cng_j021_q2","tid":"cng_j021","ty":"choice","df":"basic","p":"马六甲海峡是连接哪两个大洋的重要通道？","ch":[{"key":"A","text":"大西洋和北冰洋"},{"key":"B","text":"印度洋和北冰洋"},{"key":"C","text":"太平洋和大西洋"},{"key":"D","text":"印度洋和太平洋"}],"a":"D","ex":"马六甲海峡位于马来半岛与苏门答腊岛之间。"},{"id":"cng_j021_q3","tid":"cng_j021","ty":"choice","df":"standard","p":"东南亚气候湿热，主要粮食作物是？","ch":[{"key":"A","text":"水稻"},{"key":"B","text":"青稞"},{"key":"C","text":"甜菜"},{"key":"D","text":"燕麦"}],"a":"A","ex":"高温多雨适合水稻生长，许多国家以稻米为主食。"},{"id":"cng_j021_q4","tid":"cng_j021","ty":"choice","df":"challenge","p":"中南半岛的城市多分布在河流沿岸及河口三角洲，主要因为？","ch":[{"key":"A","text":"海拔越高越适合居住"},{"key":"B","text":"地形平坦、水源充足、交通便利"},{"key":"C","text":"这里完全没有洪水"},{"key":"D","text":"远离所有海洋更安全"}],"a":"B","ex":"河流提供灌溉、用水和航运，河口三角洲土壤肥沃。"},{"id":"cng_j022_q1","tid":"cng_j022","ty":"choice","df":"basic","p":"印度大部分地区的气候类型是？","ch":[{"key":"A","text":"温带海洋性气候"},{"key":"B","text":"寒带气候"},{"key":"C","text":"地中海气候"},{"key":"D","text":"热带季风气候"}],"a":"D","ex":"印度大部分位于热带，受西南季风影响，分旱雨两季。"},{"id":"cng_j022_q2","tid":"cng_j022","ty":"choice","df":"basic","p":"印度人口数量在世界上的地位是？","ch":[{"key":"A","text":"居世界前列的人口大国"},{"key":"B","text":"人口最少的国家"},{"key":"C","text":"只有数百万人"},{"key":"D","text":"没有常住人口"}],"a":"A","ex":"印度是南亚面积最大、人口极多的国家。"},{"id":"cng_j022_q3","tid":"cng_j022","ty":"choice","df":"standard","p":"印度的信息技术产业中心常被称为“印度硅谷”的是？","ch":[{"key":"A","text":"新德里"},{"key":"B","text":"班加罗尔"},{"key":"C","text":"加尔各答"},{"key":"D","text":"孟买港口的渔村"}],"a":"B","ex":"班加罗尔集中了软件和服务外包产业。"},{"id":"cng_j022_q4","tid":"cng_j022","ty":"choice","df":"challenge","p":"西南季风来得晚或退得早，印度容易出现？","ch":[{"key":"A","text":"终年冰冻"},{"key":"B","text":"与季风完全无关的火山喷发"},{"key":"C","text":"旱灾，粮食减产"},{"key":"D","text":"全国同时变成温带海洋性气候"}],"a":"C","ex":"农业依赖夏季风带来的降水，季风不稳定会导致旱涝。"},{"id":"cng_j023_q1","tid":"cng_j023","ty":"choice","df":"basic","p":"俄罗斯是世界上？","ch":[{"key":"A","text":"面积最大的国家"},{"key":"B","text":"人口最多的国家"},{"key":"C","text":"海拔最高的国家"},{"key":"D","text":"唯一的岛国"}],"a":"A","ex":"俄罗斯地跨亚欧大陆，面积约 1700 多万平方千米。"},{"id":"cng_j023_q2","tid":"cng_j023","ty":"choice","df":"basic","p":"俄罗斯的亚洲部分气候以什么为主？","ch":[{"key":"A","text":"热带雨林气候"},{"key":"B","text":"温带大陆性气候，冬季漫长严寒"},{"key":"C","text":"全年高温多雨"},{"key":"D","text":"地中海气候"}],"a":"B","ex":"纬度高、距海远，冬季寒冷漫长。"},{"id":"cng_j023_q3","tid":"cng_j023","ty":"choice","df":"standard","p":"西伯利亚大铁路的走向大致是？","ch":[{"key":"A","text":"南北向穿过赤道"},{"key":"B","text":"环绕南极"},{"key":"C","text":"东西向"},{"key":"D","text":"只连接非洲各国"}],"a":"C","ex":"铁路横贯亚欧大陆，连接莫斯科与远东港口。"},{"id":"cng_j023_q4","tid":"cng_j023","ty":"choice","df":"challenge","p":"俄罗斯自然资源丰富，重工业发达，但农业相对薄弱，主要因为？","ch":[{"key":"A","text":"完全没有平原"},{"key":"B","text":"人口全部集中在热带"},{"key":"C","text":"没有铁路和河流"},{"key":"D","text":"纬度高、热量不足，耕地分布不均"}],"a":"D","ex":"热量条件限制农作物种类和产量，工业则依托矿产和能源。"},{"id":"cng_j024_q1","tid":"cng_j024","ty":"choice","df":"basic","p":"西亚地处亚、欧、非三洲交界，被称为？","ch":[{"key":"A","text":"世界屋脊"},{"key":"B","text":"“三洲五海之地”"},{"key":"C","text":"地球的极点"},{"key":"D","text":"太平洋上的群岛"}],"a":"B","ex":"西亚濒临地中海、红海、黑海、阿拉伯海和里海，位置重要。"},{"id":"cng_j024_q2","tid":"cng_j024","ty":"choice","df":"basic","p":"西亚大部分地区的气候特点是？","ch":[{"key":"A","text":"终年寒冷多雨"},{"key":"B","text":"与热带雨林相同"},{"key":"C","text":"炎热干燥"},{"key":"D","text":"没有沙漠"}],"a":"C","ex":"北回归线穿过，副高和信风影响，热带沙漠气候广布。"},{"id":"cng_j024_q3","tid":"cng_j024","ty":"choice","df":"standard","p":"西亚被称为“世界石油宝库”，石油主要分布在？","ch":[{"key":"A","text":"青藏高原内部"},{"key":"B","text":"北冰洋沿岸苔原"},{"key":"C","text":"马来群岛全部岛屿"},{"key":"D","text":"波斯湾及其沿岸"}],"a":"D","ex":"波斯湾沿岸是世界石油储量、产量和出口量最大的地区之一。"},{"id":"cng_j024_q4","tid":"cng_j024","ty":"choice","df":"challenge","p":"西亚许多国家淡水资源短缺，传统农业多分布在？","ch":[{"key":"A","text":"有河流或绿洲的地方"},{"key":"B","text":"所有沙漠腹地的沙丘顶"},{"key":"C","text":"全年冰雪覆盖的高山内部"},{"key":"D","text":"没有水源的戈壁中心"}],"a":"A","ex":"两河流域、尼罗河下游附近以及绿洲有灌溉条件。"},{"id":"cng_j025_q1","tid":"cng_j025","ty":"choice","df":"basic","p":"欧洲西部大多数国家属于？","ch":[{"key":"A","text":"最不发达国家"},{"key":"B","text":"没有工业的农业国"},{"key":"C","text":"发达国家"},{"key":"D","text":"热带沙漠国家"}],"a":"C","ex":"欧洲西部是发达国家最集中的地区之一。"},{"id":"cng_j025_q2","tid":"cng_j025","ty":"choice","df":"basic","p":"欧洲西部大西洋沿岸典型的气候是？","ch":[{"key":"A","text":"热带季风气候"},{"key":"B","text":"寒带冰原气候"},{"key":"C","text":"热带沙漠气候"},{"key":"D","text":"温带海洋性气候"}],"a":"D","ex":"常年受西风和北大西洋暖流影响，冬暖夏凉、降水均匀。"},{"id":"cng_j025_q3","tid":"cng_j025","ty":"choice","df":"standard","p":"欧洲西部旅游业发达，主要因为？","ch":[{"key":"A","text":"自然和人文旅游资源丰富，交通便利"},{"key":"B","text":"完全没有历史古迹"},{"key":"C","text":"气候全年严寒"},{"key":"D","text":"国家之间互不往来"}],"a":"A","ex":"海岸、山地、古城和博物馆等资源多样，接待能力强。"},{"id":"cng_j025_q4","tid":"cng_j025","ty":"choice","df":"challenge","p":"欧洲西部畜牧业发达，与气候的关系是？","ch":[{"key":"A","text":"全年干旱只适合骆驼"},{"key":"B","text":"温和湿润适合多汁牧草生长"},{"key":"C","text":"没有平原无法种草"},{"key":"D","text":"冬季完全没有降水"}],"a":"B","ex":"温带海洋性气候光热不足但降水均匀，有利于牧草，不利于谷物成熟。"},{"id":"cng_j026_q1","tid":"cng_j026","ty":"choice","df":"basic","p":"撒哈拉以南非洲大部分位于？","ch":[{"key":"A","text":"北寒带"},{"key":"B","text":"南寒带"},{"key":"C","text":"只有温带"},{"key":"D","text":"热带"}],"a":"D","ex":"赤道穿过中部，大部分在南北回归线之间。"},{"id":"cng_j026_q2","tid":"cng_j026","ty":"choice","df":"basic","p":"本区分布很广、分干湿两季的气候是？","ch":[{"key":"A","text":"热带草原气候"},{"key":"B","text":"温带海洋性气候"},{"key":"C","text":"冰原气候"},{"key":"D","text":"地中海气候"}],"a":"A","ex":"热带草原气候在赤道雨林两侧呈半环状分布。"},{"id":"cng_j026_q3","tid":"cng_j026","ty":"choice","df":"standard","p":"本区许多国家出口初级农矿产品，在国际贸易中往往？","ch":[{"key":"A","text":"可以任意提高制成品价格"},{"key":"B","text":"处于不利地位"},{"key":"C","text":"完全不需要进口"},{"key":"D","text":"已经全部成为发达国家"}],"a":"B","ex":"出口价格较低的原料、进口价格较高的工业制成品，贸易条件较差。"},{"id":"cng_j026_q4","tid":"cng_j026","ty":"choice","df":"challenge","p":"非洲气候类型大致关于赤道南北对称，主要因为？","ch":[{"key":"A","text":"整个非洲都在北极圈内"},{"key":"B","text":"没有高原和盆地"},{"key":"C","text":"赤道横贯中部，气压带风带对称分布"},{"key":"D","text":"洋流只影响东岸且完全相同"}],"a":"C","ex":"纬度因素使气候带以赤道为轴南北对称。"},{"id":"cng_j027_q1","tid":"cng_j027","ty":"choice","df":"basic","p":"澳大利亚是世界上唯一独占一块大陆的国家，这块大陆是？","ch":[{"key":"A","text":"澳大利亚大陆"},{"key":"B","text":"亚欧大陆"},{"key":"C","text":"北美大陆"},{"key":"D","text":"南极大陆"}],"a":"A","ex":"澳大利亚领土主体就是澳大利亚大陆，还有塔斯马尼亚岛等。"},{"id":"cng_j027_q2","tid":"cng_j027","ty":"choice","df":"basic","p":"澳大利亚因长期孤立，保留了许多？","ch":[{"key":"A","text":"只有北极熊"},{"key":"B","text":"特有的古老动物，如袋鼠、鸸鹋"},{"key":"C","text":"没有袋类动物"},{"key":"D","text":"与亚洲完全相同的野生大象群"}],"a":"B","ex":"大陆分离早，生物独立演化。"},{"id":"cng_j027_q3","tid":"cng_j027","ty":"choice","df":"standard","p":"澳大利亚气候和植被带的分布特点是？","ch":[{"key":"A","text":"南北延伸的带状且与海岸垂直"},{"key":"B","text":"只出现在内陆一点"},{"key":"C","text":"半环状"},{"key":"D","text":"完全没有干旱区"}],"a":"C","ex":"受海陆位置和降水从沿海向内陆递减影响，呈半环状。"},{"id":"cng_j027_q4","tid":"cng_j027","ty":"choice","df":"challenge","p":"澳大利亚因养羊多、出口羊毛多，被称为？","ch":[{"key":"A","text":"“世界油库”"},{"key":"B","text":"“赤道上的岛国”"},{"key":"C","text":"“冰雪大陆”"},{"key":"D","text":"“骑在羊背上的国家”"}],"a":"D","ex":"畜牧业尤其是牧羊业在国民经济和出口中地位突出；因矿产丰富也称“坐在矿车上的国家”。"},{"id":"cng_j028_q1","tid":"cng_j028","ty":"choice","df":"basic","p":"美国本土位于哪个大洲？","ch":[{"key":"A","text":"南美洲"},{"key":"B","text":"北美洲"},{"key":"C","text":"非洲"},{"key":"D","text":"大洋洲"}],"a":"B","ex":"美国主体在北美洲中部，还有阿拉斯加和夏威夷。"},{"id":"cng_j028_q2","tid":"cng_j028","ty":"choice","df":"basic","p":"美国农业的突出特点之一是？","ch":[{"key":"A","text":"完全没有种植业"},{"key":"B","text":"只在西部沙漠种水稻"},{"key":"C","text":"地区生产专业化"},{"key":"D","text":"全国只种一种作物"}],"a":"C","ex":"不同地区根据自然条件形成小麦带、玉米带、棉花带等。"},{"id":"cng_j028_q3","tid":"cng_j028","ty":"choice","df":"standard","p":"美国高新技术产业的代表地区是？","ch":[{"key":"A","text":"墨西哥高原"},{"key":"B","text":"落基山最高峰"},{"key":"C","text":"五大湖湖心岛"},{"key":"D","text":"硅谷"}],"a":"D","ex":"旧金山东南的硅谷是全球著名高科技产业区。"},{"id":"cng_j028_q4","tid":"cng_j028","ty":"choice","df":"challenge","p":"美国本土降水大致从东南向西北递减，农业带东西差异明显，主要受？","ch":[{"key":"A","text":"气候和地形等因素影响"},{"key":"B","text":"全国气候完全相同"},{"key":"C","text":"没有河流和土壤差异"},{"key":"D","text":"农业布局与自然条件无关"}],"a":"A","ex":"中部平原适合商品谷物，西部山地高原降水较少，农业类型不同。"},{"id":"cng_j029_q1","tid":"cng_j029","ty":"choice","df":"basic","p":"巴西大部分位于？","ch":[{"key":"A","text":"北美洲西部"},{"key":"B","text":"非洲北部"},{"key":"C","text":"南美洲东部，赤道和南回归线之间"},{"key":"D","text":"欧洲西部"}],"a":"C","ex":"巴西是南美洲面积最大的国家，领土主要在热带。"},{"id":"cng_j029_q2","tid":"cng_j029","ty":"choice","df":"basic","p":"世界上面积最大的热带雨林主要分布在巴西的？","ch":[{"key":"A","text":"东南沿海的所有沙漠"},{"key":"B","text":"巴塔哥尼亚高原"},{"key":"C","text":"安第斯山脉山顶"},{"key":"D","text":"亚马孙河流域"}],"a":"D","ex":"亚马孙平原高温多雨，发育了世界最大的热带雨林。"},{"id":"cng_j029_q3","tid":"cng_j029","ty":"choice","df":"standard","p":"巴西人口和城市主要集中在？","ch":[{"key":"A","text":"东南沿海"},{"key":"B","text":"亚马孙雨林内部"},{"key":"C","text":"西部安第斯高山"},{"key":"D","text":"赤道正中的原始密林腹地"}],"a":"A","ex":"东南沿海气候较温和、开发早、交通便利。"},{"id":"cng_j029_q4","tid":"cng_j029","ty":"choice","df":"challenge","p":"保护亚马孙热带雨林的重要意义是？","ch":[{"key":"A","text":"让雨林完全消失以扩大城市"},{"key":"B","text":"维护全球气候和生物多样性"},{"key":"C","text":"雨林对地球环境没有作用"},{"key":"D","text":"只影响南极冰川、与巴西无关"}],"a":"B","ex":"雨林通过光合作用吸收二氧化碳、释放氧气，并保存大量物种。"},{"id":"cng_j030_q1","tid":"cng_j030","ty":"choice","df":"basic","p":"南极地区是地球上最冷的地区之一，被称为？","ch":[{"key":"A","text":"热带雨林"},{"key":"B","text":"世界油库"},{"key":"C","text":"鱼米之乡"},{"key":"D","text":"“冰雪高原”"}],"a":"D","ex":"南极大陆平均海拔高、冰层厚，酷寒、烈风、干燥。"},{"id":"cng_j030_q2","tid":"cng_j030","ty":"choice","df":"basic","p":"北极地区的中心是？","ch":[{"key":"A","text":"北冰洋"},{"key":"B","text":"南极大陆"},{"key":"C","text":"青藏高原"},{"key":"D","text":"撒哈拉沙漠"}],"a":"A","ex":"北极点位于北冰洋上，周围是亚洲、欧洲和北美洲的北部。"},{"id":"cng_j030_q3","tid":"cng_j030","ty":"choice","df":"standard","p":"到南极考察应选择的季节是北半球的？","ch":[{"key":"A","text":"夏季"},{"key":"B","text":"冬季"},{"key":"C","text":"与季节无关，全年皆宜且同样温暖"},{"key":"D","text":"只有春分日"}],"a":"B","ex":"南北半球季节相反，北半球冬季正值南极暖季，有极昼。"},{"id":"cng_j030_q4","tid":"cng_j030","ty":"choice","df":"challenge","p":"极地地区对全球的意义突出表现在？","ch":[{"key":"A","text":"可以大规模开垦农田"},{"key":"B","text":"气候与全球变暖毫无关系"},{"key":"C","text":"调节全球气候，并具有科研价值"},{"key":"D","text":"没有独特的自然环境"}],"a":"C","ex":"冰盖反射阳光、影响洋流和大气环流；还保存气候和环境演变信息。"},{"id":"cng_j031_q1","tid":"cng_j031","ty":"choice","df":"basic","p":"我国领土面积大约是？","ch":[{"key":"A","text":"960 万平方千米"},{"key":"B","text":"90 万平方千米"},{"key":"C","text":"9.6 万平方千米"},{"key":"D","text":"1700 万平方千米"}],"a":"A","ex":"我国陆地领土面积约 960 万平方千米，居世界第三位。"},{"id":"cng_j031_q2","tid":"cng_j031","ty":"choice","df":"basic","p":"我国最东端在黑龙江与乌苏里江主航道中心线的相交处，最西端在？","ch":[{"key":"A","text":"曾母暗沙"},{"key":"B","text":"新疆帕米尔高原"},{"key":"C","text":"漠河以北的黑龙江主航道中心线"},{"key":"D","text":"海南岛南部"}],"a":"B","ex":"东西端经度差大，最西端位于帕米尔高原。"},{"id":"cng_j031_q3","tid":"cng_j031","ty":"choice","df":"standard","p":"我国大陆海岸线漫长，濒临的海洋自北向南依次是？","ch":[{"key":"A","text":"南海、东海、黄海、渤海"},{"key":"B","text":"北海、地中海、红海、阿拉伯海"},{"key":"C","text":"渤海、黄海、东海、南海"},{"key":"D","text":"北冰洋、大西洋、印度洋、太平洋"}],"a":"C","ex":"东部自北向南濒临渤海、黄海、东海、南海。"},{"id":"cng_j031_q4","tid":"cng_j031","ty":"choice","df":"challenge","p":"我国陆上邻国有 14 个，与韩国、日本等是？","ch":[{"key":"A","text":"陆上接壤的邻国"},{"key":"B","text":"没有海洋相隔的内陆国"},{"key":"C","text":"位于南美洲的国家"},{"key":"D","text":"隔海相望的国家"}],"a":"D","ex":"朝鲜、韩国、日本、菲律宾、马来西亚、文莱、印度尼西亚等隔海相望（教材常列 6 个隔海相望国家）。"},{"id":"cng_j032_q1","tid":"cng_j032","ty":"choice","df":"basic","p":"我国是世界上人口最多的国家之一，人口分布的基本特点是？","ch":[{"key":"A","text":"西北多、东南少"},{"key":"B","text":"东南多、西北少"},{"key":"C","text":"均匀分布"},{"key":"D","text":"只集中在青藏高原"}],"a":"B","ex":"黑河—腾冲一线以东人口稠密，以西稀疏。"},{"id":"cng_j032_q2","tid":"cng_j032","ty":"choice","df":"basic","p":"黑河—腾冲一线是我国重要的？","ch":[{"key":"A","text":"赤道"},{"key":"B","text":"北回归线"},{"key":"C","text":"人口地理分界线"},{"key":"D","text":"地势第一、二级阶梯分界线"}],"a":"C","ex":"该线以东面积约占 43%，人口占 90% 以上。"},{"id":"cng_j032_q3","tid":"cng_j032","ty":"choice","df":"standard","p":"人口过多会带来的突出问题是？","ch":[{"key":"A","text":"耕地会自动增加"},{"key":"B","text":"所有资源都变得取之不尽"},{"key":"C","text":"自然灾害完全消失"},{"key":"D","text":"就业、教育和资源环境压力增大"}],"a":"D","ex":"人口基数大，资源、环境和公共服务压力大。"},{"id":"cng_j032_q4","tid":"cng_j032","ty":"choice","df":"challenge","p":"我国把计划生育作为基本国策后，近年来又调整生育政策，主要是为了？","ch":[{"key":"A","text":"促进人口长期均衡发展"},{"key":"B","text":"使人口无限增长"},{"key":"C","text":"完全停止人口流动"},{"key":"D","text":"取消所有公共服务"}],"a":"A","ex":"政策随人口形势调整，既要控制过快增长，也要应对老龄化等问题。"},{"id":"cng_j033_q1","tid":"cng_j033","ty":"choice","df":"basic","p":"我国共有多少个民族？","ch":[{"key":"A","text":"55 个"},{"key":"B","text":"16 个"},{"key":"C","text":"56 个"},{"key":"D","text":"1 个"}],"a":"C","ex":"汉族和 55 个少数民族，共 56 个民族。"},{"id":"cng_j033_q2","tid":"cng_j033","ty":"choice","df":"basic","p":"汉族人口最多，少数民族主要分布在？","ch":[{"key":"A","text":"只有东南沿海大城市"},{"key":"B","text":"全部集中在华北平原中部"},{"key":"C","text":"只分布在海南岛"},{"key":"D","text":"西南、西北和东北等地"}],"a":"D","ex":"少数民族多分布在边疆的西南、西北和东北地区。"},{"id":"cng_j033_q3","tid":"cng_j033","ty":"choice","df":"standard","p":"我国民族分布的特点常概括为？","ch":[{"key":"A","text":"大杂居、小聚居、交错居住"},{"key":"B","text":"完全按省界隔离"},{"key":"C","text":"汉族只住西部"},{"key":"D","text":"少数民族只住东部沿海"}],"a":"A","ex":"各民族既有相对集中的聚居区，又广泛交错居住。"},{"id":"cng_j033_q4","tid":"cng_j033","ty":"choice","df":"challenge","p":"各少数民族都有使用和发展自己语言文字的自由，体现了？","ch":[{"key":"A","text":"只允许一种语言存在"},{"key":"B","text":"民族平等和民族团结"},{"key":"C","text":"民族文化必须全部消失"},{"key":"D","text":"民族区域与国家无关"}],"a":"B","ex":"宪法保障各民族的平等权利和文化传承。"},{"id":"cng_j034_q1","tid":"cng_j034","ty":"choice","df":"basic","p":"我国地势的基本特征是？","ch":[{"key":"A","text":"东高西低，呈一级斜坡"},{"key":"B","text":"南北高、中间低"},{"key":"C","text":"四周高、中间是海洋"},{"key":"D","text":"西高东低，呈三级阶梯"}],"a":"D","ex":"青藏高原为第一级阶梯，向东逐级降低。"},{"id":"cng_j034_q2","tid":"cng_j034","ty":"choice","df":"basic","p":"第一级阶梯和第二级阶梯的分界山脉包括？","ch":[{"key":"A","text":"昆仑山、祁连山、横断山脉"},{"key":"B","text":"大兴安岭、太行山、巫山、雪峰山"},{"key":"C","text":"长白山、武夷山"},{"key":"D","text":"喜马拉雅山南坡全部"}],"a":"A","ex":"昆仑—祁连—横断一线是一、二级阶梯分界。"},{"id":"cng_j034_q3","tid":"cng_j034","ty":"choice","df":"standard","p":"我国面积最大的高原是？","ch":[{"key":"A","text":"黄土高原"},{"key":"B","text":"青藏高原"},{"key":"C","text":"云贵高原"},{"key":"D","text":"内蒙古高原"}],"a":"B","ex":"青藏高原有“世界屋脊”之称，面积最大、海拔最高。"},{"id":"cng_j034_q4","tid":"cng_j034","ty":"choice","df":"challenge","p":"西高东低的地势对河流的影响是？","ch":[{"key":"A","text":"所有河流都向西流入内陆"},{"key":"B","text":"没有落差，不能发电"},{"key":"C","text":"许多大河东流入海，水能资源丰富"},{"key":"D","text":"河流无法形成"}],"a":"C","ex":"地势使长江、黄河等东流入海，在阶梯交界处落差大、水能丰富。"},{"id":"cng_j035_q1","tid":"cng_j035","ty":"choice","df":"basic","p":"我国气候的显著特征之一是？","ch":[{"key":"A","text":"季风气候显著"},{"key":"B","text":"全年受西风带控制"},{"key":"C","text":"没有季节变化"},{"key":"D","text":"全国都是热带雨林气候"}],"a":"A","ex":"冬夏季风交替，大多数地方雨热同期。"},{"id":"cng_j035_q2","tid":"cng_j035","ty":"choice","df":"basic","p":"我国冬季南北温差很大，主要因为？","ch":[{"key":"A","text":"地势完全平坦"},{"key":"B","text":"纬度差异大，北方正午太阳高度小、白昼短"},{"key":"C","text":"没有冬季风"},{"key":"D","text":"南方一定没有阳光"}],"a":"B","ex":"冬季太阳直射南半球，北方正午太阳高度更低、白昼更短，又受冬季风影响。"},{"id":"cng_j035_q3","tid":"cng_j035","ty":"choice","df":"standard","p":"夏季风从海洋吹向陆地，使我国东部？","ch":[{"key":"A","text":"全年滴雨没有"},{"key":"B","text":"只有冬季下雨"},{"key":"C","text":"降水较多，且集中在夏季"},{"key":"D","text":"降水与季风无关"}],"a":"C","ex":"夏季风带来水汽，形成雨季；冬季风来自内陆，降水少。"},{"id":"cng_j035_q4","tid":"cng_j035","ty":"choice","df":"challenge","p":"西北内陆气候干旱，主要因为？","ch":[{"key":"A","text":"纬度一定比海南更低"},{"key":"B","text":"海拔一定低于海平面"},{"key":"C","text":"全年受台风控制"},{"key":"D","text":"距海远，湿润气流难以到达"}],"a":"D","ex":"海陆位置使水汽递减，加上山脉阻挡，降水稀少。"},{"id":"cng_j036_q1","tid":"cng_j036","ty":"choice","df":"basic","p":"我国最长的河流是？","ch":[{"key":"A","text":"黄河"},{"key":"B","text":"长江"},{"key":"C","text":"珠江"},{"key":"D","text":"塔里木河"}],"a":"B","ex":"长江全长约 6300 千米，是我国第一大河。"},{"id":"cng_j036_q2","tid":"cng_j036","ty":"choice","df":"basic","p":"黄河中游流经黄土高原，突出的水文特征是？","ch":[{"key":"A","text":"流量比长江更大"},{"key":"B","text":"没有结冰期"},{"key":"C","text":"含沙量很大"},{"key":"D","text":"是淡水湖"}],"a":"C","ex":"黄土土质疏松，水土流失严重，使黄河成为含沙量最大的河流之一。"},{"id":"cng_j036_q3","tid":"cng_j036","ty":"choice","df":"standard","p":"长江水能资源主要集中在？","ch":[{"key":"A","text":"入海口附近的三角洲"},{"key":"B","text":"下游平原的所有河段"},{"key":"C","text":"没有落差的河段"},{"key":"D","text":"上游河段"}],"a":"D","ex":"上游流经地势阶梯交界处，落差大、水流急。"},{"id":"cng_j036_q4","tid":"cng_j036","ty":"choice","df":"challenge","p":"鄱阳湖、洞庭湖等属于？","ch":[{"key":"A","text":"外流区的淡水湖"},{"key":"B","text":"内流区的咸水湖"},{"key":"C","text":"海洋的一部分"},{"key":"D","text":"人工运河"}],"a":"A","ex":"它们位于东部外流区，湖水最终注入海洋，是淡水湖。"},{"id":"cng_j037_q1","tid":"cng_j037","ty":"choice","df":"basic","p":"我国土地资源的特点是？","ch":[{"key":"A","text":"耕地占国土的绝大部分"},{"key":"B","text":"没有草地和林地"},{"key":"C","text":"总量丰富，人均不足，山地多、耕地少"},{"key":"D","text":"人均耕地远高于世界平均水平"}],"a":"C","ex":"国土辽阔但人口多，山地、高原比重大，耕地比重小。"},{"id":"cng_j037_q2","tid":"cng_j037","ty":"choice","df":"basic","p":"耕地主要分布在？","ch":[{"key":"A","text":"青藏高原的所有冰川上"},{"key":"B","text":"西北沙漠的流动沙丘顶"},{"key":"C","text":"横断山区的陡坡绝壁"},{"key":"D","text":"东部季风区的平原和盆地"}],"a":"D","ex":"平原、盆地热量水分条件较好，是耕地集中区。"},{"id":"cng_j037_q3","tid":"cng_j037","ty":"choice","df":"standard","p":"北方耕地多、南方耕地相对较少且破碎，与此对应的主食差异是？","ch":[{"key":"A","text":"北方多小麦，南方多水稻"},{"key":"B","text":"北方只种青稞，南方只种甜菜"},{"key":"C","text":"完全没有差异"},{"key":"D","text":"南北都只能种甘蔗"}],"a":"A","ex":"旱地和水田的分布与气候、耕作习惯有关。"},{"id":"cng_j037_q4","tid":"cng_j037","ty":"choice","df":"challenge","p":"保护耕地的正确做法是？","ch":[{"key":"A","text":"随意占用基本农田建厂房"},{"key":"B","text":"严格保护耕地，合理规划建设用地"},{"key":"C","text":"把所有林地改成耕地"},{"key":"D","text":"抛荒所有耕地"}],"a":"B","ex":"十分珍惜、合理利用土地和切实保护耕地是基本国策。"},{"id":"cng_j038_q1","tid":"cng_j038","ty":"choice","df":"basic","p":"我国水资源的空间分布特点是？","ch":[{"key":"A","text":"西多东少、北多南少"},{"key":"B","text":"各地完全均匀"},{"key":"C","text":"只有西北最多"},{"key":"D","text":"东多西少、南多北少"}],"a":"D","ex":"降水东多西少、南多北少，径流分布与此一致。"},{"id":"cng_j038_q2","tid":"cng_j038","ty":"choice","df":"basic","p":"我国水资源时间分配的特点是？","ch":[{"key":"A","text":"夏秋多、冬春少，年际变化大"},{"key":"B","text":"全年各月完全均匀"},{"key":"C","text":"只有冬季有水"},{"key":"D","text":"与降水无关"}],"a":"A","ex":"降水集中在夏秋，导致河川径流季节变化大。"},{"id":"cng_j038_q3","tid":"cng_j038","ty":"choice","df":"standard","p":"缓解北方缺水的跨流域调水工程是？","ch":[{"key":"A","text":"西气东输"},{"key":"B","text":"南水北调"},{"key":"C","text":"青藏铁路"},{"key":"D","text":"三峡只有防洪功能、完全不供水"}],"a":"B","ex":"南水北调把长江流域的水调到华北、西北。"},{"id":"cng_j038_q4","tid":"cng_j038","ty":"choice","df":"challenge","p":"解决水资源问题，除了调水和兴修水利，还必须？","ch":[{"key":"A","text":"鼓励浪费水"},{"key":"B","text":"把所有河流填平"},{"key":"C","text":"节约用水、防治水污染"},{"key":"D","text":"停止一切农业生产"}],"a":"C","ex":"开源与节流并重，保护水质同样重要。"},{"id":"cng_j039_q1","tid":"cng_j039","ty":"choice","df":"basic","p":"我国矿产资源的基本特点是？","ch":[{"key":"A","text":"种类多、储量较丰富，但人均较少"},{"key":"B","text":"完全没有煤炭"},{"key":"C","text":"只有黄金一种矿产"},{"key":"D","text":"人均占有量远超所有国家"}],"a":"A","ex":"总量不小，但人口多，人均不足，且贫矿、伴生矿较多。"},{"id":"cng_j039_q2","tid":"cng_j039","ty":"choice","df":"basic","p":"我国煤炭资源在北方较为集中，著名煤海是？","ch":[{"key":"A","text":"海南省"},{"key":"B","text":"山西省"},{"key":"C","text":"青藏高原腹地"},{"key":"D","text":"珠江口"}],"a":"B","ex":"山西煤炭储量和产量长期居前列，有“煤海”之称。"},{"id":"cng_j039_q3","tid":"cng_j039","ty":"choice","df":"standard","p":"石油资源比较集中的地区包括？","ch":[{"key":"A","text":"只有青藏高原内部"},{"key":"B","text":"东南丘陵的所有山顶"},{"key":"C","text":"东北、西北和沿海大陆架"},{"key":"D","text":"长江中下游平原的水稻田"}],"a":"C","ex":"大庆、新疆以及渤海、南海等海域是重要石油产区。"},{"id":"cng_j039_q4","tid":"cng_j039","ty":"choice","df":"challenge","p":"合理开发利用矿产资源，应当？","ch":[{"key":"A","text":"无节制开采所有矿山"},{"key":"B","text":"禁止任何勘探"},{"key":"C","text":"只出口原矿、不发展加工"},{"key":"D","text":"提高利用率，保护环境，开发新能源"}],"a":"D","ex":"矿产不可再生，需要节约、综合利用并发展清洁能源。"},{"id":"cng_j040_q1","tid":"cng_j040","ty":"choice","df":"basic","p":"我国既是陆地大国，也是海洋大国，管辖的海域面积约？","ch":[{"key":"A","text":"960 万平方千米"},{"key":"B","text":"300 万平方千米"},{"key":"C","text":"3 万平方千米"},{"key":"D","text":"只有内陆湖泊"}],"a":"B","ex":"大陆海岸线长，主张管辖海域面积约 300 万平方千米。"},{"id":"cng_j040_q2","tid":"cng_j040","ty":"choice","df":"basic","p":"舟山渔场成为我国最大渔场，主要因为？","ch":[{"key":"A","text":"完全没有大陆架"},{"key":"B","text":"海水终年冰冻"},{"key":"C","text":"寒暖流交汇、长江等径流带来养分"},{"key":"D","text":"地处内陆盆地"}],"a":"C","ex":"大陆架宽浅、饵料丰富，形成著名渔场。"},{"id":"cng_j040_q3","tid":"cng_j040","ty":"choice","df":"standard","p":"在南海等海域开发油气资源，首先应当？","ch":[{"key":"A","text":"放弃全部岛屿"},{"key":"B","text":"禁止任何科学考察"},{"key":"C","text":"把领海全部让出"},{"key":"D","text":"维护海洋权益，依法开发"}],"a":"D","ex":"海洋资源开发以国家主权和海洋权益为前提。"},{"id":"cng_j040_q4","tid":"cng_j040","ty":"choice","df":"challenge","p":"保护海洋资源的正确做法是？","ch":[{"key":"A","text":"合理捕捞、防治污染、保护滩涂和红树林"},{"key":"B","text":"竭泽而渔"},{"key":"C","text":"向海洋倾倒全部工业废水"},{"key":"D","text":"填平所有海湾"}],"a":"A","ex":"海洋生态一旦破坏很难恢复，需要可持续利用。"},{"id":"cng_j041_q1","tid":"cng_j041","ty":"choice","df":"basic","p":"我国农业的地区分布，大体是？","ch":[{"key":"A","text":"全国都只发展渔业"},{"key":"B","text":"西部全是水田"},{"key":"C","text":"东部以种植业为主，西部以畜牧业为主"},{"key":"D","text":"东部没有任何农业"}],"a":"C","ex":"受降水和地形影响，农耕区主要在东部季风区。"},{"id":"cng_j041_q2","tid":"cng_j041","ty":"choice","df":"basic","p":"秦岭—淮河以南的耕地多是？","ch":[{"key":"A","text":"旱地，只能种春小麦"},{"key":"B","text":"高寒牧场"},{"key":"C","text":"无法耕作的石漠"},{"key":"D","text":"水田，主要种植水稻"}],"a":"D","ex":"南方热量充足、降水丰富，以水田稻作农业为主。"},{"id":"cng_j041_q3","tid":"cng_j041","ty":"choice","df":"standard","p":"东北平原能够成为重要商品粮基地，有利条件包括？","ch":[{"key":"A","text":"耕地集中连片、土壤肥沃、地广人稀"},{"key":"B","text":"完全没有黑土"},{"key":"C","text":"气候终年炎热多雨"},{"key":"D","text":"人均耕地极少"}],"a":"A","ex":"黑土肥沃，平原广阔，粮食商品率高。"},{"id":"cng_j041_q4","tid":"cng_j041","ty":"choice","df":"challenge","p":"因地制宜发展农业，意味着？","ch":[{"key":"A","text":"到处都种同一种作物"},{"key":"B","text":"根据自然条件和社会需求安排农业生产"},{"key":"C","text":"不考虑水源和热量"},{"key":"D","text":"把所有草地开垦为耕地"}],"a":"B","ex":"宜林则林、宜牧则牧、宜粮则粮，才能持续发展。"},{"id":"cng_j042_q1","tid":"cng_j042","ty":"choice","df":"basic","p":"我国四大工业基地都位于？","ch":[{"key":"A","text":"青藏高原内部"},{"key":"B","text":"西北沙漠腹地"},{"key":"C","text":"横断山区"},{"key":"D","text":"东部沿海地区"}],"a":"D","ex":"辽中南、京津唐、沪宁杭、珠江三角洲都在东部沿海。"},{"id":"cng_j042_q2","tid":"cng_j042","ty":"choice","df":"basic","p":"沪宁杭工业基地的特点是？","ch":[{"key":"A","text":"综合性工业基地，轻重工业都发达"},{"key":"B","text":"只有煤炭开采"},{"key":"C","text":"完全没有制造业"},{"key":"D","text":"以高寒畜牧业为主"}],"a":"A","ex":"以上海为中心，工业部门齐全。"},{"id":"cng_j042_q3","tid":"cng_j042","ty":"choice","df":"standard","p":"高新技术产业往往靠近？","ch":[{"key":"A","text":"没有高校的偏远矿区"},{"key":"B","text":"科技发达的大城市和交通便利地区"},{"key":"C","text":"终年冰冻的极地"},{"key":"D","text":"与人才和交通无关的地方"}],"a":"B","ex":"技术和人才是高新技术产业的关键区位。"},{"id":"cng_j042_q4","tid":"cng_j042","ty":"choice","df":"challenge","p":"辽中南工业基地传统上以重工业为主，近年来面临的问题是？","ch":[{"key":"A","text":"劳动力和原料都无限增长"},{"key":"B","text":"已经没有任何工业"},{"key":"C","text":"资源枯竭和产业结构偏重，需要转型升级"},{"key":"D","text":"气候突然变成热带雨林"}],"a":"C","ex":"老工业基地需要技术改造和发展新兴产业。"},{"id":"cng_j043_q1","tid":"cng_j043","ty":"choice","df":"basic","p":"现代交通运输方式中，运量大、运费较低、速度较慢的是？","ch":[{"key":"A","text":"水路运输"},{"key":"B","text":"航空运输"},{"key":"C","text":"公路短途的出租车"},{"key":"D","text":"管道运输天然气以外的所有旅客"}],"a":"A","ex":"水运适合大宗货物长距离运输，但速度慢。"},{"id":"cng_j043_q2","tid":"cng_j043","ty":"choice","df":"basic","p":"我国铁路网的格局常概括为？","ch":[{"key":"A","text":"只有一条环状铁路"},{"key":"B","text":"“五纵三横”等干线构成骨架"},{"key":"C","text":"完全没有南北向铁路"},{"key":"D","text":"铁路只分布在青藏高原"}],"a":"B","ex":"京沪、京九、京广、焦柳、宝成—成昆等南北干线，以及滨洲—滨绥、京包—包兰、陇海—兰新、沪杭—浙赣—湘黔—贵昆等东西干线。"},{"id":"cng_j043_q3","tid":"cng_j043","ty":"choice","df":"standard","p":"西藏结束没有铁路历史的标志性工程是？","ch":[{"key":"A","text":"京沪高铁"},{"key":"B","text":"京杭运河"},{"key":"C","text":"青藏铁路"},{"key":"D","text":"珠江口大桥"}],"a":"C","ex":"青藏铁路从西宁到拉萨，是世界海拔最高的铁路之一。"},{"id":"cng_j043_q4","tid":"cng_j043","ty":"choice","df":"challenge","p":"选择运输方式时，贵重急需的少量货物通常优先？","ch":[{"key":"A","text":"内河慢船"},{"key":"B","text":"人力挑担且不限时间"},{"key":"C","text":"完全不考虑时效"},{"key":"D","text":"航空运输"}],"a":"D","ex":"航空速度快，适合急需、贵重、量小的货物。"},{"id":"cng_j044_q1","tid":"cng_j044","ty":"choice","df":"basic","p":"我国是自然灾害多发的国家，常见的气象灾害有？","ch":[{"key":"A","text":"只有火山喷发"},{"key":"B","text":"干旱、洪涝、台风、寒潮等"},{"key":"C","text":"完全没有地震"},{"key":"D","text":"只有极光"}],"a":"B","ex":"季风气候不稳定，旱涝、台风和寒潮都较频繁。"},{"id":"cng_j044_q2","tid":"cng_j044","ty":"choice","df":"basic","p":"台风主要影响我国的？","ch":[{"key":"A","text":"西北内陆沙漠"},{"key":"B","text":"青藏高原腹地"},{"key":"C","text":"东南沿海地区"},{"key":"D","text":"东北的所有高山顶部"}],"a":"C","ex":"台风从西北太平洋生成，登陆东南沿海。"},{"id":"cng_j044_q3","tid":"cng_j044","ty":"choice","df":"standard","p":"地震多发生在？","ch":[{"key":"A","text":"平原中心且从未有断层的地方"},{"key":"B","text":"只有赤道"},{"key":"C","text":"与地质构造无关的所有地点"},{"key":"D","text":"地壳活跃的板块交界或断裂带"}],"a":"D","ex":"我国地处环太平洋和地中海—喜马拉雅地震带。"},{"id":"cng_j044_q4","tid":"cng_j044","ty":"choice","df":"challenge","p":"面对自然灾害，正确的做法是？","ch":[{"key":"A","text":"监测预警、工程防御、应急避险和灾后重建"},{"key":"B","text":"完全不设防"},{"key":"C","text":"灾害来临时再考虑逃生且不需要演练"},{"key":"D","text":"破坏所有气象观测站"}],"a":"A","ex":"防灾减灾需要工程措施和非工程措施结合。"},{"id":"cng_j045_q1","tid":"cng_j045","ty":"choice","df":"basic","p":"我国面临的环境问题包括？","ch":[{"key":"A","text":"只有噪声、没有其他问题"},{"key":"B","text":"环境已经没有任何压力"},{"key":"C","text":"大气污染、水污染、水土流失、土地荒漠化等"},{"key":"D","text":"与人类活动无关"}],"a":"C","ex":"工业化和城市化过程中，污染和生态破坏都较突出。"},{"id":"cng_j045_q2","tid":"cng_j045","ty":"choice","df":"basic","p":"黄土高原最突出的生态问题是？","ch":[{"key":"A","text":"热带雨林消失"},{"key":"B","text":"海平面上升导致全境被淹"},{"key":"C","text":"没有河流"},{"key":"D","text":"水土流失"}],"a":"D","ex":"土质疏松、降水集中、植被破坏导致水土流失。"},{"id":"cng_j045_q3","tid":"cng_j045","ty":"choice","df":"standard","p":"建设美丽中国，要求走的道路是？","ch":[{"key":"A","text":"绿色发展、循环发展、低碳发展"},{"key":"B","text":"先污染后治理且不必修复"},{"key":"C","text":"放弃所有经济发展"},{"key":"D","text":"只保护城市、不管乡村"}],"a":"A","ex":"经济发展与环境保护要统一，建设生态文明。"},{"id":"cng_j045_q4","tid":"cng_j045","ty":"choice","df":"challenge","p":"个人参与环境保护，可行的做法是？","ch":[{"key":"A","text":"随意丢弃废电池"},{"key":"B","text":"节约资源、垃圾分类、绿色出行"},{"key":"C","text":"浪费水电"},{"key":"D","text":"焚烧秸秆和垃圾"}],"a":"B","ex":"生活方式的改变是生态文明的重要组成部分。"},{"id":"cng_j046_q1","tid":"cng_j046","ty":"choice","df":"basic","p":"我国四大地理区域是？","ch":[{"key":"A","text":"只有东部和西部"},{"key":"B","text":"七大洲的别称"},{"key":"C","text":"没有区域差异"},{"key":"D","text":"北方地区、南方地区、西北地区、青藏地区"}],"a":"D","ex":"综合自然和人文地理特征，划分为这四大区域。"},{"id":"cng_j046_q2","tid":"cng_j046","ty":"choice","df":"basic","p":"北方地区和南方地区的分界线大致是？","ch":[{"key":"A","text":"秦岭—淮河一线"},{"key":"B","text":"长城"},{"key":"C","text":"黄河"},{"key":"D","text":"北回归线"}],"a":"A","ex":"该线与 1 月 0℃等温线、800 毫米年等降水量线大体一致。"},{"id":"cng_j046_q3","tid":"cng_j046","ty":"choice","df":"standard","p":"西北地区与北方地区的分界，大致相当于？","ch":[{"key":"A","text":"赤道"},{"key":"B","text":"400 毫米年等降水量线"},{"key":"C","text":"南极圈"},{"key":"D","text":"海岸线"}],"a":"B","ex":"400 毫米等降水量线大致是季风区与非季风区、农耕区与畜牧区的界线。"},{"id":"cng_j046_q4","tid":"cng_j046","ty":"choice","df":"challenge","p":"青藏地区与其他地区的分界主要依据是？","ch":[{"key":"A","text":"经度完全相同"},{"key":"B","text":"人口数量完全相等"},{"key":"C","text":"地势第一级阶梯的边缘"},{"key":"D","text":"与地形无关的铁路"}],"a":"C","ex":"昆仑山—祁连山—横断山脉一线既是阶梯分界，也是青藏地区的边界。"},{"id":"cng_j047_q1","tid":"cng_j047","ty":"choice","df":"basic","p":"北方地区主要位于？","ch":[{"key":"A","text":"秦岭—淮河以北的东部季风区"},{"key":"B","text":"青藏高原内部"},{"key":"C","text":"华南沿海的全部岛屿"},{"key":"D","text":"西北沙漠腹地"}],"a":"A","ex":"包括东北、华北和黄土高原等。"},{"id":"cng_j047_q2","tid":"cng_j047","ty":"choice","df":"basic","p":"北方地区的耕地以什么为主？","ch":[{"key":"A","text":"水田"},{"key":"B","text":"旱地"},{"key":"C","text":"高寒牧场"},{"key":"D","text":"无法耕作的石山"}],"a":"B","ex":"降水较少，耕地多为旱地，主要种植小麦、玉米等。"},{"id":"cng_j047_q3","tid":"cng_j047","ty":"choice","df":"standard","p":"华北平原春旱较严重，主要因为？","ch":[{"key":"A","text":"夏季完全没有雨"},{"key":"B","text":"冬季气温过高"},{"key":"C","text":"春季降水少、升温快、蒸发旺，又正值作物需水期"},{"key":"D","text":"没有河流和地下水"}],"a":"C","ex":"春旱是华北农业的重要限制因素。"},{"id":"cng_j047_q4","tid":"cng_j047","ty":"choice","df":"challenge","p":"东北平原可以大规模机械化耕作，有利条件是？","ch":[{"key":"A","text":"地块极其破碎"},{"key":"B","text":"全部是陡坡梯田"},{"key":"C","text":"劳动力比土地还密集且无法使用机器"},{"key":"D","text":"地势平坦、耕地连片、人均耕地多"}],"a":"D","ex":"平原开阔，适合大型农机作业。"},{"id":"cng_j048_q1","tid":"cng_j048","ty":"choice","df":"basic","p":"东北三省是指？","ch":[{"key":"A","text":"河北、山西、山东"},{"key":"B","text":"黑龙江、吉林、辽宁"},{"key":"C","text":"江苏、浙江、上海"},{"key":"D","text":"新疆、西藏、青海"}],"a":"B","ex":"三省合称东北三省，白山黑水是其代称。"},{"id":"cng_j048_q2","tid":"cng_j048","ty":"choice","df":"basic","p":"东北平原土壤肥沃，典型土壤是？","ch":[{"key":"A","text":"红壤"},{"key":"B","text":"荒漠土"},{"key":"C","text":"黑土"},{"key":"D","text":"水稻土遍布所有山地"}],"a":"C","ex":"冷湿环境下形成的黑土有机质含量高。"},{"id":"cng_j048_q3","tid":"cng_j048","ty":"choice","df":"standard","p":"传统上，辽中南工业基地依赖的资源主要是？","ch":[{"key":"A","text":"热带经济作物"},{"key":"B","text":"海洋渔业以外没有任何资源"},{"key":"C","text":"高寒草场"},{"key":"D","text":"煤、铁等矿产资源"}],"a":"D","ex":"鞍山、抚顺等地煤铁资源促进了重工业发展。"},{"id":"cng_j048_q4","tid":"cng_j048","ty":"choice","df":"challenge","p":"过度开垦和黑土流失会使东北商品粮基地？","ch":[{"key":"A","text":"土壤肥力下降，需要保护性耕作"},{"key":"B","text":"黑土自动增厚"},{"key":"C","text":"气候变成热带雨林"},{"key":"D","text":"与生态保护无关"}],"a":"A","ex":"黑土退化是东北农业可持续发展的突出问题。"},{"id":"cng_j049_q1","tid":"cng_j049","ty":"choice","df":"basic","p":"黄土高原是世界上最大的黄土堆积区，主要位于？","ch":[{"key":"A","text":"长江入海口"},{"key":"B","text":"珠江三角洲"},{"key":"C","text":"黄河中游"},{"key":"D","text":"塔里木盆地"}],"a":"C","ex":"山西、陕西、宁夏、甘肃等省区的大部分属于黄土高原。"},{"id":"cng_j049_q2","tid":"cng_j049","ty":"choice","df":"basic","p":"黄土高原千沟万壑的地表，主要是因为？","ch":[{"key":"A","text":"全年没有降水"},{"key":"B","text":"冰川覆盖全部地表"},{"key":"C","text":"海水长期浸泡"},{"key":"D","text":"水土流失严重"}],"a":"D","ex":"土质疏松、夏季暴雨、植被破坏导致沟谷发育。"},{"id":"cng_j049_q3","tid":"cng_j049","ty":"choice","df":"standard","p":"治理黄土高原水土流失的生物措施是？","ch":[{"key":"A","text":"植树种草"},{"key":"B","text":"把所有坡地改成陡坡耕种"},{"key":"C","text":"砍伐全部植被"},{"key":"D","text":"填平黄河"}],"a":"A","ex":"恢复植被可以保持水土；工程措施还有修梯田、打坝淤地等。"},{"id":"cng_j049_q4","tid":"cng_j049","ty":"choice","df":"challenge","p":"黄土土质疏松、直立性强，传统民居是？","ch":[{"key":"A","text":"吊脚楼"},{"key":"B","text":"窑洞"},{"key":"C","text":"冰屋"},{"key":"D","text":"竹楼"}],"a":"B","ex":"黄土便于开挖窑洞，冬暖夏凉。"},{"id":"cng_j050_q1","tid":"cng_j050","ty":"choice","df":"basic","p":"北京是我国的？","ch":[{"key":"A","text":"最大的海港城市"},{"key":"B","text":"位于南海的经济特区"},{"key":"C","text":"西北的石油基地"},{"key":"D","text":"首都，也是政治、文化中心和国际交往中心"}],"a":"D","ex":"北京是中华人民共和国的首都。"},{"id":"cng_j050_q2","tid":"cng_j050","ty":"choice","df":"basic","p":"北京的地势特点是？","ch":[{"key":"A","text":"西北高、东南低"},{"key":"B","text":"东南高、西北低"},{"key":"C","text":"完全平坦且四周是海"},{"key":"D","text":"中部是世界最高峰"}],"a":"A","ex":"西面是西山，北面是军都山，东南是平原。"},{"id":"cng_j050_q3","tid":"cng_j050","ty":"choice","df":"standard","p":"为减轻交通和环境压力，北京在城市建设中注重？","ch":[{"key":"A","text":"无限扩大高耗能工业"},{"key":"B","text":"发展公共交通、保护历史文化名城、疏解非首都功能"},{"key":"C","text":"拆除全部文物"},{"key":"D","text":"填平所有绿地"}],"a":"B","ex":"北京既要保障首都功能，也要治理“大城市病”。"},{"id":"cng_j050_q4","tid":"cng_j050","ty":"choice","df":"challenge","p":"北京的水资源紧张，可行的措施包括？","ch":[{"key":"A","text":"鼓励浪费用水"},{"key":"B","text":"把密云水库排空"},{"key":"C","text":"节约用水、污水回用，并接受南水北调供水"},{"key":"D","text":"停止所有绿化"}],"a":"C","ex":"开源节流并重，是缺水城市的共同选择。"},{"id":"cng_j051_q1","tid":"cng_j051","ty":"choice","df":"basic","p":"南方地区位于秦岭—淮河以南、青藏高原以东，气候以什么为主？","ch":[{"key":"A","text":"亚热带、热带季风气候"},{"key":"B","text":"温带大陆性气候"},{"key":"C","text":"寒带气候"},{"key":"D","text":"高原山地气候遍布所有平原"}],"a":"A","ex":"夏季高温多雨，冬季温和少雨。"},{"id":"cng_j051_q2","tid":"cng_j051","ty":"choice","df":"basic","p":"南方地区耕地多是？","ch":[{"key":"A","text":"旱地小麦连作"},{"key":"B","text":"水田"},{"key":"C","text":"高寒牧场"},{"key":"D","text":"无法灌溉的沙漠"}],"a":"B","ex":"降水丰富，水田比重大，水稻是主要粮食作物。"},{"id":"cng_j051_q3","tid":"cng_j051","ty":"choice","df":"standard","p":"南方地区红壤较广，土壤特点是？","ch":[{"key":"A","text":"黑土那样极为肥沃且遍布东北以外所有山地"},{"key":"B","text":"完全是盐碱地"},{"key":"C","text":"酸性较强、有机质较少"},{"key":"D","text":"与气候无关"}],"a":"C","ex":"高温多雨使养分淋溶，红壤需要改良。"},{"id":"cng_j051_q4","tid":"cng_j051","ty":"choice","df":"challenge","p":"长江中下游有“鱼米之乡”之称，因为？","ch":[{"key":"A","text":"完全没有河流"},{"key":"B","text":"只产青稞和牦牛"},{"key":"C","text":"气候干旱只能放牧"},{"key":"D","text":"水田广布、河湖众多，稻米和淡水鱼产量大"}],"a":"D","ex":"河网密、热量足，农业和渔业都发达。"},{"id":"cng_j052_q1","tid":"cng_j052","ty":"choice","df":"basic","p":"长江三角洲位于？","ch":[{"key":"A","text":"黄河源头"},{"key":"B","text":"长江入海口附近"},{"key":"C","text":"珠江口以西的全部高原"},{"key":"D","text":"塔里木盆地"}],"a":"B","ex":"长江与沿海交汇，包括上海、江苏南部和浙江北部等。"},{"id":"cng_j052_q2","tid":"cng_j052","ty":"choice","df":"basic","p":"长江三角洲最大的城市、我国最大的城市是？","ch":[{"key":"A","text":"拉萨"},{"key":"B","text":"乌鲁木齐"},{"key":"C","text":"上海"},{"key":"D","text":"哈尔滨"}],"a":"C","ex":"上海是直辖市，也是长江三角洲的核心城市。"},{"id":"cng_j052_q3","tid":"cng_j052","ty":"choice","df":"standard","p":"本区能够成为我国经济最发达地区之一，有利条件包括？","ch":[{"key":"A","text":"远离海洋和长江"},{"key":"B","text":"没有港口"},{"key":"C","text":"交通闭塞"},{"key":"D","text":"河海交汇、平原广阔、劳动力素质高、腹地广阔"}],"a":"D","ex":"江海联运和发达的交通网络是重要优势。"},{"id":"cng_j052_q4","tid":"cng_j052","ty":"choice","df":"challenge","p":"杭州、苏州等城市以园林和历史遗迹著称，说明本区？","ch":[{"key":"A","text":"自然与人文旅游资源都很丰富"},{"key":"B","text":"完全没有文化底蕴"},{"key":"C","text":"只能发展重工业"},{"key":"D","text":"与水乡风貌无关"}],"a":"A","ex":"水乡、古镇和园林是长江三角洲的文化特色。"},{"id":"cng_j053_q1","tid":"cng_j053","ty":"choice","df":"basic","p":"香港和澳门是我国的？","ch":[{"key":"A","text":"省"},{"key":"B","text":"自治区"},{"key":"C","text":"特别行政区"},{"key":"D","text":"直辖市"}],"a":"C","ex":"1997 年香港回归，1999 年澳门回归，设立特别行政区。"},{"id":"cng_j053_q2","tid":"cng_j053","ty":"choice","df":"basic","p":"香港位于珠江口的？","ch":[{"key":"A","text":"西侧，北与珠海相邻"},{"key":"B","text":"长江入海口"},{"key":"C","text":"渤海湾内部"},{"key":"D","text":"东侧，北与深圳相邻"}],"a":"D","ex":"澳门在珠江口西侧，北与珠海相邻。"},{"id":"cng_j053_q3","tid":"cng_j053","ty":"choice","df":"standard","p":"香港经济的重要支柱包括？","ch":[{"key":"A","text":"对外贸易、金融、航运和旅游业"},{"key":"B","text":"高寒畜牧业"},{"key":"C","text":"大规模种植小麦"},{"key":"D","text":"没有服务业"}],"a":"A","ex":"香港是国际金融、贸易和航运中心之一。"},{"id":"cng_j053_q4","tid":"cng_j053","ty":"choice","df":"challenge","p":"祖国内地与香港、澳门的关系可以概括为？","ch":[{"key":"A","text":"彼此隔绝"},{"key":"B","text":"优势互补、互惠互利"},{"key":"C","text":"香港澳门不需要内地的物资和空间"},{"key":"D","text":"内地不需要港澳的资金和技术"}],"a":"B","ex":"内地提供土地、资源和市场，港澳提供资金、技术和管理经验。"},{"id":"cng_j054_q1","tid":"cng_j054","ty":"choice","df":"basic","p":"台湾岛是我国面积最大的岛屿，西隔什么与福建省相望？","ch":[{"key":"A","text":"琼州海峡"},{"key":"B","text":"渤海海峡"},{"key":"C","text":"马六甲海峡"},{"key":"D","text":"台湾海峡"}],"a":"D","ex":"台湾海峡连接东海和南海。"},{"id":"cng_j054_q2","tid":"cng_j054","ty":"choice","df":"basic","p":"台湾岛的地形以什么为主？","ch":[{"key":"A","text":"山地"},{"key":"B","text":"平原占绝大部分"},{"key":"C","text":"沙漠"},{"key":"D","text":"冰川覆盖全岛"}],"a":"A","ex":"东部和中部多山，西部有狭窄平原。"},{"id":"cng_j054_q3","tid":"cng_j054","ty":"choice","df":"standard","p":"台湾因物产丰富被称为“祖国东南海上的明珠”，盛产？","ch":[{"key":"A","text":"青稞和甜菜"},{"key":"B","text":"稻米、甘蔗、热带和亚热带水果"},{"key":"C","text":"只有石油、没有农产品"},{"key":"D","text":"终年冰雪、没有森林"}],"a":"B","ex":"气候湿热，农业和森林资源丰富。"},{"id":"cng_j054_q4","tid":"cng_j054","ty":"choice","df":"challenge","p":"台湾是中国不可分割的一部分，其居民祖籍多在？","ch":[{"key":"A","text":"欧洲各国"},{"key":"B","text":"南极科考站"},{"key":"C","text":"福建、广东等省"},{"key":"D","text":"中亚内陆国家"}],"a":"C","ex":"历史上大量移民来自闽粤，语言文化与祖国大陆一脉相承。"},{"id":"cng_j055_q1","tid":"cng_j055","ty":"choice","df":"basic","p":"西北地区最显著的自然特征是？","ch":[{"key":"A","text":"干旱"},{"key":"B","text":"湿热"},{"key":"C","text":"高寒且降水极为丰富"},{"key":"D","text":"与江南水乡相同"}],"a":"A","ex":"深居内陆、距海遥远，降水稀少。"},{"id":"cng_j055_q2","tid":"cng_j055","ty":"choice","df":"basic","p":"从东到西，西北地区的自然景观大致是？","ch":[{"key":"A","text":"森林—雨林—海洋"},{"key":"B","text":"草原—荒漠草原—荒漠"},{"key":"C","text":"水田—丘陵—雪山且降水递增"},{"key":"D","text":"与距海远近无关"}],"a":"B","ex":"降水自东向西递减，植被随之变化。"},{"id":"cng_j055_q3","tid":"cng_j055","ty":"choice","df":"standard","p":"本区农业以畜牧业和灌溉农业为主，灌溉水源主要来自？","ch":[{"key":"A","text":"丰沛的台风雨"},{"key":"B","text":"赤道对流雨"},{"key":"C","text":"高山冰雪融水和地下水"},{"key":"D","text":"当地全年的暴雨"}],"a":"C","ex":"天山、祁连山等高山冰雪融水补给绿洲。"},{"id":"cng_j055_q4","tid":"cng_j055","ty":"choice","df":"challenge","p":"过度放牧和开垦会导致？","ch":[{"key":"A","text":"草原自动恢复且无需管理"},{"key":"B","text":"降水突然增加到江南水平"},{"key":"C","text":"沙漠全部变成水田"},{"key":"D","text":"土地荒漠化加剧"}],"a":"D","ex":"干旱区生态脆弱，必须合理放牧、保护植被。"},{"id":"cng_j056_q1","tid":"cng_j056","ty":"choice","df":"basic","p":"塔里木盆地是我国面积最大的盆地，位于？","ch":[{"key":"A","text":"四川东部"},{"key":"B","text":"新疆南部"},{"key":"C","text":"青海湖边"},{"key":"D","text":"东北平原中部"}],"a":"B","ex":"盆地周围是天山、昆仑山等山脉，内部是塔克拉玛干沙漠。"},{"id":"cng_j056_q2","tid":"cng_j056","ty":"choice","df":"basic","p":"盆地边缘出现串珠状绿洲，主要因为？","ch":[{"key":"A","text":"盆地中心降水最多"},{"key":"B","text":"绿洲与水源无关"},{"key":"C","text":"高山冰雪融水在山麓形成水源"},{"key":"D","text":"全年受台风灌溉"}],"a":"C","ex":"冰雪融水出山后，在冲积扇前缘形成绿洲。"},{"id":"cng_j056_q3","tid":"cng_j056","ty":"choice","df":"standard","p":"西气东输工程的气源地之一是？","ch":[{"key":"A","text":"珠江三角洲的水田"},{"key":"B","text":"长江三角洲的全部港口"},{"key":"C","text":"东南沿海的渔场"},{"key":"D","text":"塔里木盆地的天然气田"}],"a":"D","ex":"轮南等地的天然气通过管道输往上海等东部城市。"},{"id":"cng_j056_q4","tid":"cng_j056","ty":"choice","df":"challenge","p":"在塔里木盆地发展农业，必须特别注意？","ch":[{"key":"A","text":"节约用水，保护绿洲生态"},{"key":"B","text":"大水漫灌且开垦全部沙漠"},{"key":"C","text":"砍伐全部胡杨"},{"key":"D","text":"把内流河引入海洋"}],"a":"A","ex":"水资源是绿洲的生命线，过度用水会使河流下游和植被衰退。"},{"id":"cng_j057_q1","tid":"cng_j057","ty":"choice","df":"basic","p":"青藏地区的突出自然特征是？","ch":[{"key":"A","text":"炎热干燥"},{"key":"B","text":"低温潮湿且全是平原"},{"key":"C","text":"高寒"},{"key":"D","text":"与华北平原完全相同"}],"a":"C","ex":"平均海拔 4000 米以上，空气稀薄、气温低。"},{"id":"cng_j057_q2","tid":"cng_j057","ty":"choice","df":"basic","p":"本区的主要牲畜是？","ch":[{"key":"A","text":"亚洲象"},{"key":"B","text":"袋鼠"},{"key":"C","text":"北极熊"},{"key":"D","text":"牦牛、藏绵羊等"}],"a":"D","ex":"牦牛适应高寒缺氧环境，有“高原之舟”之称。"},{"id":"cng_j057_q3","tid":"cng_j057","ty":"choice","df":"standard","p":"青藏地区的农业主要分布在？","ch":[{"key":"A","text":"海拔较低的河谷，如湟水谷地、雅鲁藏布江谷地"},{"key":"B","text":"所有冰川表面"},{"key":"C","text":"盆地中心的流动沙丘"},{"key":"D","text":"东海海面"}],"a":"A","ex":"河谷海拔较低、气温较高，可发展河谷农业，种植青稞、小麦等。"},{"id":"cng_j057_q4","tid":"cng_j057","ty":"choice","df":"challenge","p":"太阳能、地热能丰富，主要因为？","ch":[{"key":"A","text":"全年阴雨"},{"key":"B","text":"海拔高、空气稀薄、晴天多，以及地处板块交界"},{"key":"C","text":"位于海洋深处"},{"key":"D","text":"与太阳辐射无关"}],"a":"B","ex":"日照强、地热显示区多，是重要的清洁能源。"},{"id":"cng_j058_q1","tid":"cng_j058","ty":"choice","df":"basic","p":"三江源地区位于青海省南部，是哪些大河的源头？","ch":[{"key":"A","text":"珠江、淮河、松花江"},{"key":"B","text":"塔里木河、额尔齐斯河、雅鲁藏布江"},{"key":"C","text":"只是运河的源头"},{"key":"D","text":"长江、黄河、澜沧江"}],"a":"D","ex":"“中华水塔”指的就是这三条江河的源区。"},{"id":"cng_j058_q2","tid":"cng_j058","ty":"choice","df":"basic","p":"三江源生态一旦破坏，会直接影响？","ch":[{"key":"A","text":"中下游的水资源和生态安全"},{"key":"B","text":"只有青海湖的盐度"},{"key":"C","text":"与长江黄河无关"},{"key":"D","text":"只改变南极冰盖"}],"a":"A","ex":"源区的冰川、湖泊和湿地是河流的补给来源。"},{"id":"cng_j058_q3","tid":"cng_j058","ty":"choice","df":"standard","p":"保护三江源的重要措施是？","ch":[{"key":"A","text":"大规模开垦湿地"},{"key":"B","text":"退牧还草、保护湿地和野生动物"},{"key":"C","text":"在源区建设高耗水工业"},{"key":"D","text":"捕杀珍稀动物"}],"a":"B","ex":"设立三江源国家公园，限制过度放牧和不合理开发。"},{"id":"cng_j058_q4","tid":"cng_j058","ty":"choice","df":"challenge","p":"近年来三江源局部生态好转，说明？","ch":[{"key":"A","text":"高寒区生态破坏后绝对无法恢复"},{"key":"B","text":"保护工作没有意义"},{"key":"C","text":"科学保护和恢复可以改善高寒区生态"},{"key":"D","text":"冰川融化对河流没有影响"}],"a":"C","ex":"退牧还草、人工增雨和巡护等措施已见到成效，但仍需长期坚持。"},{"id":"cng_j059_q1","tid":"cng_j059","ty":"choice","df":"basic","p":"我国目前仍是世界上最大的？","ch":[{"key":"A","text":"发展中国家"},{"key":"B","text":"发达国家"},{"key":"C","text":"没有工业的国家"},{"key":"D","text":"面积最小的国家"}],"a":"A","ex":"经济总量居世界前列，但人均水平和发展不平衡问题仍然存在。"},{"id":"cng_j059_q2","tid":"cng_j059","ty":"choice","df":"basic","p":"2013 年我国提出的国际合作倡议是？","ch":[{"key":"A","text":"闭关锁国"},{"key":"B","text":"“一带一路”"},{"key":"C","text":"停止所有对外贸易"},{"key":"D","text":"只与一个大洲往来"}],"a":"B","ex":"共建丝绸之路经济带和 21 世纪海上丝绸之路。"},{"id":"cng_j059_q3","tid":"cng_j059","ty":"choice","df":"standard","p":"我国发展中面临的挑战包括？","ch":[{"key":"A","text":"已经没有任何挑战"},{"key":"B","text":"人口、资源和环境完全协调"},{"key":"C","text":"资源环境压力、区域发展不平衡、维护海洋权益等"},{"key":"D","text":"不需要参与国际事务"}],"a":"C","ex":"国情决定了必须走可持续发展道路。"},{"id":"cng_j059_q4","tid":"cng_j059","ty":"choice","df":"challenge","p":"我国用占世界很少的耕地养活了占世界约五分之一的人口，同时积极参与国际事务，说明？","ch":[{"key":"A","text":"中国不承担国际责任"},{"key":"B","text":"粮食安全与世界无关"},{"key":"C","text":"发展成就可以忽视环境保护"},{"key":"D","text":"中国是负责任的大国"}],"a":"D","ex":"粮食安全和对外援助、国际合作都体现大国责任。"}];
